IG$.olapReportView = function(uid, canvas, owner, fsize) {
	var me = this;
	
	me.mresult = null;
	me.reportoption = null;
	me.sheetoption = null;
	me.uid = uid;
	me.jobid = null;
	me.maincontainer = canvas;
	me.owner = owner;
	me.maincontainer = owner;
	me.container = $("<div class='igc-rpt-view'></div>").appendTo(owner);
	me.width = 0;
	me.height = 0;
	me.ctrl = null;
	me.fsize = fsize;
	me.sheetobj = null;
	
	me._mgrid = new IG$.V$grid();
	
	me._mgrid.sheetoption = me.sheetoption;
	me._mgrid.size = me.fsize;
	me._mgrid.initialize(me.container);
	me._mgrid.sheetobj = me.sheetobj;
	
	me.fcontainer = $("<div class='idv-filter-desc'></div>").appendTo(me.maincontainer).hide();
	
	/*
	if (me._mgrid.ctx)
	{
		var ctx = me._mgrid.ctx;
		
		ctx.bind({
			itemclick: function(renderer) {
			},
			doubleclick: function(renderer) {
			},
			selectionchanged: function(renderer) {
			},
			menu: function(el) {
			}
		});
	}
	*/
	me.applyOptions();
}

