						chart: null,
						code: "",
						index: 0,
						mcol: 0,
						merged: 0,
						mrow: 0,
						pindex: 0,
						position: 9,
						stylename: "LineNumber_" + (i < me.mresult.rowfix ? "header" : "data"),
						text: (i < me.mresult.rowfix ? "" : "" + (n+1)),
						title: 0,
