	setFltInfo: function(desc) {
		var me = this,
			fcontainer = me.fcontainer,
			items,
			i, d, value;

		if (desc)
		{
			items = desc.split("\n");
			d = "";
			for (i=0; i < items.length; i++)
			{
				if (items[i])
				{
					value = items[i].substring(0, 40);
					d = (!d) ? value : d + "<br>" + value;
				}
			}
			if (d)
			{
				fcontainer.html(d).show();
			}
			
			clearTimeout(me.__fc);
			
			me.__fc = setTimeout(function() {
				fcontainer.fadeOut();
			}, 2000);
		}
		else
		{
			fcontainer.empty();
			fcontainer.hide();
		}
	},
	
	genTreeCol: function(mdata, colfix, rowfix, styles) {
		var me = this,
			data = [],
			i, j, k, k,
			row, mrow, mcell, dcell, pcell, depths, depth,
			spcols = [],
			pval, cval, nval;
		
		for (i=0; i < rowfix; i++)
		{
			row = mdata[i];
			
			mrow = [];
		
			for (j=0; j < row.length; j++)
			{
				mcell = this.getCellVal(row[j], j);
				mrow.push(mcell);
			}
			
			data.push(mrow);
		}
		
		for (i=0; i < rowfix; i++)
		{
			row = data[i];
			pcell = null;
			
			if (i < rowfix-1)
			{
				for (j=row.length-1; j>=colfix; j--)
				{
					pcell = (j > colfix) ? row[j-1] : null;
					if ((pcell != null && row[j].text != pcell.text) || j == colfix)
					{
						depth = i;
						if (row[j].haschild === true)
						{
							depth = row[j].depth;
						}
						if (i == 0 || (i > 0 && depth == i))
						{
							for (k=0; k < rowfix; k++)
							{
								if (k < i)
								{
									dcell = this.getCellVal(data[k][j], i);
									dcell.haschild = true;
									dcell.depth = depth;
									data[k].splice(j, 0, dcell);
								}
								else
								{
									dcell = this.getCellVal(row[j], i);
									dcell.haschild = true;
									dcell.depth = depth;
									data[k].splice(j, 0, dcell);
								}
							}
						}
					}
				}
			}
			
			pcell = null;
			depths = [];
			for (j=0; j < rowfix; j++)
			{
				depths[j] = null;
			}
			
			k = -1;
			
			for (j=colfix; j < row.length; j++)
			{
				if (row[j].haschild === true)
				{
					depths[row[j].depth] = j;
					k = j;
					if (row[j].depth > 0 && depths[row[j].depth-1] != null)
					{
						row[j].parent = row[depths[row[j].depth-1]];
					}
				}
				else if (k > -1)
				{
					row[j].parent = row[k];
				}
			}
		}
		
		row = data[rowfix-1];
		
		for (i=row.length-1; i >= 0; i--)
		{
			if (row[i].haschild == true)
			{
				spcols.push(i);
			}
		}
		
		// calculate merge again
		for (i=0; i < rowfix; i++)
		{
			row = data[i];
			for (j=colfix; j < row.length; j++)
			{
				pval = (j == colfix) ? null : row[j-1].code;
				cval = row[j].code;
				nval = (j + 1 < row.length) ? row[j+1].code : null;
				
				if (cval == pval == nval)
				{
					row[j].merged = 4;
				}
				else if (cval == pval)
				{
					row[j].merged = 4;
				}
				else if (cval == nval)
				{
					row[j].merged = 2;
				}
			}
		} 
		
		for (i=rowfix; i < mdata.length; i++)
		{
			mrow = [];
			row = mdata[i];
			
			for (j=0; j < row.length; j++)
			{
				mcell = row[j];
				mrow.push(mcell);
			}
			
			me.updateColTreeData(mrow, spcols, i, 0, data[rowfix-1], rowfix, colfix, styles);
			
			data.push(mrow);
		}
		
		return data;
	},
	
	updateColTreeData: function(row, spcols, rowindex, mi, headerrow, rowfix, colfix, styles) {
		var me = this,
			j, i,
			mcell, startcell, scol, rvalues = [], style, tnum, mc;
		for (j=spcols.length-1; j >= 0; j--)
		{
			scol = spcols[j];
			mcell = this.getCellVal(row[scol], rowindex);
			mcell.code = null;
			mcell.value = null;
			mcell.text = null;
			
			row.splice(spcols[j], 0, mcell);
		}
		
		for (j=0; j < rowfix; j++)
		{
			rvalues.push(0);
		}
		
		for (j=row.length-1; j >= colfix; j--)
		{
			startcell = headerrow[j];
			
			if (startcell.haschild == true)
			{
				mc = row[j];
				row[j].code = rvalues[startcell.depth  + 1];
				row[j].value = row[j].code;
				row[j].text = row[j].code;
				if (styles && styles[mc.stylename])
				{
					style = styles[mc.stylename];
					tnum = Number(mc.code);
					if (style.formatstring && isNaN(tnum) == false)
					{
						mc.text = tnum.format(style.formatstring);
						mc.value = mc.text;
					}
				}
				rvalues[startcell.depth + 1] = 0;
				rvalues[startcell.depth] += Number(row[j].code);
			}
			else
			{
				rvalues[rvalues.length - 1] += Number(row[j].code);
			}
		}
		
		if (row[0].children && row[0].children.length > 0)
		{
			for (i=0; i < row[0].children.length; i++)
			{
				me.updateColTreeData(row[0].children[i], spcols, rowindex, 1, headerrow, rowfix, colfix, styles);
			}
		}
	},
	
	dupFinalTree: function(rvalue, dcell) {
		var i, j,
			r = [],
			mr, dchild;
			
		if (rvalue && rvalue.children && rvalue.children.length > 0)
		{
			for (i=0; i < rvalue.children.length; i++)
			{
				dchild = this.getCellVal(null, -1);
				dcell.children.push(dchild);
				mr = this.dupFinalTree(rvalue.children[i], dchild);
				if (mr && mr.length > 0)
				{
					for (j=0; j < mr.length; j++)
					{
						r.push(mr[j]);
					}
				}
				else
				{
					r.push(dchild);
				}
			}
		}
		else if (dcell)
		{
			r.push(dcell);
		}
		
		return r;
	},
	
	getCellVal: function(rvalue, j) {
		var mcell;
		
		if (rvalue)
		{
			mcell = {
				code: rvalue.code,
				chart: rvalue.chart,
				index: rvalue.index,
				mcol: rvalue.mcol,
				merged: 0,
				pindex: rvalue.pindex,
				position: rvalue.position,
				stylename: rvalue.stylename,
				text: rvalue.text,
				title: rvalue.title,
				value: rvalue.value,
				treeinfo: rvalue.treeinfo || {},
				children: rvalue.children || [],
				ccol: j,
				parent: rvalue.parent
			};
		}
		else
		{
			mcell = {
				code: "",
				chart: null,
				index: null,
				mcol: null,
				merged: 0,
				pindex: null,
				position: null,
				stylename: null,
				text: null,
				title: null,
				value: null,
				treeinfo: {},
				children: [],
				ccol: j,
				parent: null
			};
		}
		
		return mcell;
	},
	
	cloneCellVal: function(rvalue, svalue) {
		rvalue.code = svalue.code;
		rvalue.chart = svalue.chart;
		rvalue.index = svalue.index;
		rvalue.mcol = svalue.mcol;
		rvalue.pindex = svalue.pindex;
		rvalue.position = svalue.position;
		rvalue.stylename = svalue.stylename;
		rvalue.text = svalue.text;
		rvalue.title = svalue.title;
		rvalue.value = svalue.value;
	},
