	applyOptions: function(rop, sop) {
		var me = this;
		
		if (rop && sop)
		{
			me.reportoption = rop;
			me.sheetoption = sop;
			
			me._mgrid.sheetoption = sop;
		}
		
		if (me.sheetoption)
		{
			me._mgrid.columnfill = me.sheetoption.model.columnfill;
		}
	},
	
	invalidateSize: function () {
		this.drawOlapResult();
	}
