IG$.gridConfig = function() {
	var me = this;
	
	me.sfields = ["fieldname", "name", "flex", "minw", "width", "hidden", "formatstring", "align", "datatype"];
	me.columns = [];
};

IG$.gridConfig.prototype = {
	loadData: function(jdoc) {
		var me = this,
			_c = me.columns,
			tnode, tnodes, i, snodes, col, j, p, v;
		
		_c.splice(0, _c.length);
		
		if (jdoc)
		{
			for (i=0; i < jdoc.length; i++)
			{
				col = {};
				for (j=0; j < me.sfields.length; j++)
				{
					p = me.sfields[j];
					v = jdoc[i][p];
					
					if (p == "minw")
					{
						if (v)
						{
							col.minWidth = Number(v);
						}
					}
					else if (p == "width")
					{
						if (v)
						{
							col.width = Number(v);
						}
					}
					else if (p == "flex")
					{
						if (v)
						{
							col.flex = Number(v);
						}
					}
					else
					{
						col[p] = v;
					}
				}
				_c.push(col);
			}
		}
	},
	getXML: function() {
		var me = this,
			t = [],
			col,
			i, _c = me.columns,
			sfields = me.sfields,
			v, f;
			
		for (i=0; i < _c.length; i++)
		{
			col = {};
			for (j=0; j < sfields.length; j++)
			{
				f = sfields[j];
				v = _c[i][f];
				
				if (f == "minw")
				{
					v = "" + (v ? v : "");
				}
				else if (f == "width")
				{
					v = "" + (v ? v : "");
				}
				else if (f == "flex")
				{
					v = "" + (v ? v : "");
				}
				col[f] = v;
			}
			t.push(col);
		}
		
		return t;
	}
};
 
IG$.interactiveGrid = IG$.extend(IG$.ctrlBase, {
	type: "grid",
	initComponent: function() {
		var me = this;
		me.activeIndex = 0;
		me.p.push(
			{name: "cell_click", type: "event"},
			{name: "flexHeight", type: "property", datatype: "number", value: 0},
			{name: "minHeight", type: "property", datatype: "number", value: 0},
			{name: "text", type: "property", datatype: "string"},
			{name: "selectionmode", type: "property", datatype: "string", value: "none",
				"enum": [
					{name: "none", value: "none"},
					{name: "single", value: "single"},
					{name: "multi", value: "multi"}
				]
			},
			{name: "selheader", type: "property", datatype: "string", value: ""}
		);
		
		me._cinfo = new IG$.gridConfig();
		
		me.superclass.prototype.initComponent.call(me);
	},
	
	processEvent: function(evttype, obj) {
	},

	invalidate: function () {
		var me = this,
			viewer = me.viewer;
		viewer && viewer.$ex.adjust();
	},
	
	initDrawing: function () {
		var me = this,
			actionlist = me.ctrl.actionlist,
			pdb = me.ctrl.parentcontrol,
			cbtn;
		
		me._cinfo.loadData(me.layout._xparam);
		
		if (!me.viewer)
		{
			me.viewer = new $s.gridpanel({
				renderTo: me.el$,
				autofit: true,
				header: false,
				move: false,
				columns: [
				],
				listeners: {
					cellclick: function(grid, node, cellIndex, record, rowIndex, e) {
						if (actionlist["cell_click"])
						{
							me.triggerEvent("cell_click", {
								ctrl: me.ctrl,
								ptr: me,
								event: "cell_click"
							});
							/*
							pdb.executeAction.call(pdb, actionlist["cell_click"], {
								ctrl: me.ctrl,
								ptr: me,
								event: "cell_click"
							});
							*/
						}
					}
				}
			});
		}
		
		me.validateColumns();
		
		if (me.dsmode)
		{
			cbtn = $("<div class='igc-p-config' style='z-index: 10'><div class='igc-p-config-bg'></div><button>Config</button></div>").appendTo(me.html);
			$("button", cbtn).bind("click", function() {
				me.configComponent.call(me);
			});
		}
		
		me.tl$.hide();
		me.__pcinit();
	},

	configComponent: function() {
		var me = this,
			pop = new IG$.interactiveGridConfig({
				instance: me.instance,
				_cinfo: me._cinfo,
				callback: new IG$.callBackObj(me, function(dlg, sheetview) {
					me.layout._xparam = me._cinfo.getXML();
					me.validateColumns();
				}, me.viewer)
			});
		
		IG$.checkLogin(this, pop);
	},
	updateProperty: function(kname, value) {
		var me = this,
			viewer = me.viewer,
			_cinfo = me._cinfo;
		
		if (me.dsmode)
		{
			return;
		}
		
		switch(kname)
		{
		case "report_control":
			break;
		case "text":
			break;
		case "selectionmode":
			if (value && _cinfo.selmodel != value)
			{
				_cinfo.selmodel = value;
				me.validateColumns(true);
			}
			break;
		}
	},
	
	applyDataSet: function(value) {
		var me = this,
			dp = [],
			i, j,
			cols = me._cinfo.columns || [],
			col,
			r, row, c, cell, v, ld,
			hmap = {},
			fd;
		
		if (value.data)
		{
			for (i=0; i < value.headers.length; i++)
			{
				hmap[value.headers[i]] = i + 1;
			}
			for (i=0; i < value.data.length; i++)
			{
				r = value.data[i];
				row = {};
				for (j=0; j < cols.length; j++)
				{
					col = cols[j];
					fd = col.fieldname || "field_" + j;
					v = hmap[fd] ? r[hmap[fd] - 1] : "";

					if (v && col.datatype == "date")
					{
						ld = Number(v);
						if (isNaN(ld) == false)
						{
							var d = new Date(ld);
							const yyyy = d.getFullYear();
							let mm = d.getMonth() + 1; // Months start at 0!
							let dd = d.getDate();
							
							if (dd < 10) dd = '0' + dd;
							if (mm < 10) mm = '0' + mm;
							
							v = yyyy + "-" + mm + "-" + dd;
						}
					}

					row[fd] = v;
				}
				dp.push(row);
			}
		}
		this.viewer.store.loadData(dp);
	},

	updateLayout: function() {
		var me = this,
			dashboard = me.ctrl.dashboard;
	},
	
	validateColumns: function(recreate) {
		var me = this,
			viewer = me.viewer,
			store, cols = [],
			_cinfo = me._cinfo,
			_c = _cinfo.columns,
			ci,
			i, fields = [], c,
			actionlist = me.ctrl.actionlist,
			pdb = me.ctrl.parentcontrol,
			sm, stype;
			
		if (recreate)
		{
			viewer.close();
			
			if (_cinfo.selmodel == "single" || _cinfo.selmodel == "multi")
			{
				stype = "checkboxmodel";
				sm = {
					selection: "checkboxmodel",
					checkSelector: ".x-grid-cell",
					mode: _cinfo.selmodel == "single" ? "SINGLE" : "MULTI"
				};
			}
			
			viewer = me.viewer = new $s.gridpanel({
				renderTo: me.el$,
				selType: stype,
				selModel: sm,
				disabled: me.dsmode,
				columns: [
				],
				listeners: {
					cellclick: function(grid, node, cellIndex, record, rowIndex, e) {
						if (actionlist["cell_click"])
						{
							me.triggerEvent("cell_click", {
								ctrl: me.ctrl,
								ptr: me,
								event: "cell_click"
							});
							/*
							pdb.executeAction.call(pdb, actionlist["cell_click"], {
								ctrl: me.ctrl,
								ptr: me,
								event: "cell_click"
							});
							*/
						}
					}
				}
			})
		}
			
		if (viewer)
		{
			for (i=0; i < _c.length; i++)
			{
				ci = _c[i];
				ci.fieldname = ci.fieldname || "field_" + i;
				c = {
					xtype: "gridcolumn",
					text: (ci.name || ci.fieldname),
					dataIndex: ci.fieldname,
					minWidth: ci.minw || 50,
					hidden: !me.dsmode && ci.hidden ? true : false,
					align: ci.align || "left"
				};
				if (ci.width)
				{
					c.width = Number(ci.width);
				}
				else if (ci.flex)
				{
					c.flex = Number(ci.flex);
				}
				
				fields.push(c.dataIndex);
				cols.push(c);
			}
			
			store = {
				fields: fields
			};
			
			viewer.reconfigure(store, cols);
		}
	},

	getSelectionData: function(param) {
		var me = this,
			filteritems,
			i, j,
			viewer = me.viewer,
			berr = [],
			fitem,
			bs,
			rval = [],
			value,
			sel, rec;

		if (param && param.name && viewer)
		{
			sel = viewer.getSelectionModel().selected;
			
			if (sel && sel.length)
			{
				rec = sel.items[0];
				value = rec.get(param.name);
				value && rval.push({code: value, value: value});
			}
		}

		return rval;
	},
	
	selRow: function() {
		return this.viewer.getSelectionModel().selected;
	},
	
	selRowCnt: function() {
		var r = this.selRow().length;
		return r;
	},
	
	selColInfo: function(cindex) {
		var me = this,
			r,
			m = me.selRow(),
			rec, dataindex = cindex,
			cols = me.viewer.columns;
		
		if (m && m.length)
		{
			rec = m.items[0];
			if (typeof(cindex) == "string")
			{
				dataindex = cindex;
			}
			else 
			{
				if (cols && cols.length > cindex)
				{
					dataindex = cols[cindex].dataIndex;
				}
			}
			r = rec.get(dataindex);
		}
		
		return r;
	},
	
	cell: function(r, c) {
		var me = this,
			cell,
			viewer = me.viewer,
			store = viewer.store,
			i, rec,
			cols = this.viewer.columnManager.columns,
			col = cols[c];
			
		rec = store.data.items[r];
		
		if (rec && col)
		{
			cell = rec.get(col.dataIndex);
		}
		
		return cell;
	}
});

IG$.controls.grid = new IG$.interactiveGrid({}, null);

IG$.interactiveGridConfig = $s.extend($s.window, {
	
	modal: false,
	isWindow: true,
	region:"center",
	layout: "fit",
	
	closable: false,
	resizable:false,
	width: 700,
	height: 450,
	
	reportoption: null,
	
	callback: null,
	
	init_f: function() {
		var panel = this,
			grd = panel.grd;
			
		panel._cinfo && grd.store.loadData(panel._cinfo.columns);
	},
	
	toolbarHandler: function(cmd) {
		var me = this,
			grd = me.grd,
			sel,
			i;
			
		switch (cmd)
		{
		case "c_add":
			grd.store.add({
				minw: 100
			});
			break;
		case "c_del":
			sel = grd.getSelectionModel().selected;
			for (i=sel.length-1; i>=0; i--)
			{
				grd.store.remove(sel.items[i]);
			}
			break;
		}
	},
	
	moveGrid: function(grid, direction) {
		var records = grid.getSelectionModel().getSelection(),
			record = records.length ? records[0] : null;
			
		if (!record) 
		{
			return;
		}
		
		var oindex = grid.getStore().indexOf(record),
			index = oindex,
			mobj;
		
		if (direction < 0) 
		{
			index--;
			if (index < 0) 
			{
				return;
			}
		} 
		else 
		{
			index++;
			if (index >= grid.getStore().getCount()) 
			{
				return;
			}
		}
		
		grid.getStore().remove(record);
		record = grid.getStore().insert(index, record);
		grid.getSelectionModel().select(record, true);
	},
	
	_confirm: function() {
		var me = this,
			_cinfo = me._cinfo,
			cols = me._cinfo.columns,
			grd = me.grd,
			sfields = me.sfields,
			i, rec,
			c;
			
		cols.splice(0, cols.length);
		
		for (i=0; i < grd.store.data.length; i++)
		{
			rec = grd.store.data.items[i];
			c = {};
			$.each(sfields, function(m, k) {
				c[k] = rec.get(k);
			});
			cols.push(c);
		}
		
		me.callback && me.callback.execute();
		
		me.close();
	},
	
	initComponent : function() {
		var panel = this,
			sfields = this._cinfo.sfields;
			
		panel.sfields = sfields;
		
		$s.apply(this, {
			title: IRm$.r1("T_GRD_CFG"),
			items: [
				{
					xtype: "panel",
					layout: {
						type: "vbox",
						align: "stretch"
					},
					padding: ig$.padding,
					tbar: [
						{
							text: IRm$.r1("B_ADD"),
							handler: function() {
								this.toolbarHandler("c_add");
							},
							scope: this
						},
						{
							text: IRm$.r1("B_DELETE"),
							handler: function() {
								this.toolbarHandler("c_del");
							},
							scope: this
						},
						{
							text: IRm$.r1("L_MOVE_UP"),
							handler: function() {
								var me = this;
								me.moveGrid(me.grd, -1);
							},
							scope: this
						},
						{
							text: IRm$.r1("L_MOVE_DOWN"),
							handler: function() {
								var me = this;
								me.moveGrid(me.grd, 1);
							},
							scope: this
						}
					],
					items: [
						{
							xtype: "gridpanel",
							flex: 1,
							name: "grd",
							selType: "checkboxmodel",
							selModel: {
								checkSelector: ".x-grid-cell",
								mode: "MULTI"
							},
							sortableColumns: false,
							plugins: [
								{
									ptype: "cellediting",
									clicksToEdit: true
								}
							],
							store: {
								fields: sfields
							},
							columns: [
								{
									text: IRm$.r1("L_FIELD_NAME"), // "Field name",
									dataIndex: "fieldname",
									flex: 1,
									editor: {
										allowBlank: false
									}
								},
								{
									text: IRm$.r1("L_HEADER"), // "Header",
									dataIndex: "name",
									flex: 1,
									editor: {
										allowBlank: false
									}
								},
								{
									text: IRm$.r1("L_MIN_WIDTH"), // "Min Width",
									dataIndex: "minw",
									width: 80,
									editor: {
										xtype: "numberfield",
										allowBlank: false
									}
								},
								{
									text: IRm$.r1("L_WIDTH"), // "Min Width",
									dataIndex: "width",
									width: 80,
									editor: {
										xtype: "numberfield",
										allowBlank: false
									}
								},
								{
									text: IRm$.r1("L_WIDTH_FLEX"), // "Width Flex",
									dataIndex: "flex",
									width: 80,
									editor: {
										xtype: "numberfield",
										allowBlank: true
									}
								},
								{
									xtype: "checkcolumn",
									text: IRm$.r1("L_HIDDEN"), // "Hidden",
									dataIndex: "hidden",
									width: 80
								},
								{
									text: IRm$.r1("L_ALIGN"), // "Align",
									dataIndex: "align",
									width: 80,
									editor: {
										allowBlank: true,
										xtype: "combobox",
										displayField: "name",
										valueField: "value",
										store: {
											xtype: "store",
											data: [
												{name: "LEFT", value: "left"},
												{name: "RIGHT", value: "right"},
												{name: "CENTER", value: "center"}
											]
										}
									}
								},
								{
									text: IRm$.r1("L_DATATYPE"), // "Align",
									dataIndex: "datatype",
									width: 80,
									editor: {
										allowBlank: true,
										xtype: "combobox",
										displayField: "name",
										valueField: "value",
										store: {
											xtype: "store",
											data: [
												{name: "NONE", value: ""},
												{name: "STRING", value: "string"},
												{name: "DATE", value: "date"},
												{name: "INTEGER", value: "integer"},
												{name: "DOUBLE", value: "double"}
											]
										}
									}
								}
							]
						}
					]
				}
			],
			buttons:[
				"->",
				{
					text: IRm$.r1("B_CONFIRM"),
					bodyCls: "ig-btn-confirm",
					handler: function() {
						this._confirm();
					},
					scope: this
				}, {
					text: IRm$.r1("B_CANCEL"),
					handler:function() {
						this.close();
					},
					scope: this
				}
			],
			listeners: {
				afterrender: function(ui) {
					var panel = this;
					panel.grd = panel.down("[name=grd]");
					panel.init_f();
				}
			}
		});
		
		IG$.interactiveGridConfig.superclass.initComponent.apply(this, arguments);
	}
});