/***********************************************************************
 * AppPageControl: DateField 
 */
 IG$.ctrlDateField = IG$.extend(IG$.ctrlBase, {
	type: "datechooser",
	initComponent: function() {
		var me = this;
		
		me.p.push(
			{name: "text", type: "property", datatype: "string"},
			{name: "fieldlabel", type: "property", datatype: "string"}
		);
		
		me.superclass.prototype.initComponent.call(me);
	},

	updateProperty: function(kname, value) {
		var me = this,
			cmp$ = me.cmp$;
		
		switch (kname)
		{
		case "text":
			if (me.datefield)
			{
				var cdate = null;

				try
				{
					cdate = value ? new Date(value) : null;
				}
				catch (e)
				{
					cdate = null;
				}

				me.datefield.datepicker("setDate", cdate);
			}
			break;
		}
	},
	
	initDrawing: function () {
		var me = this,
			fid = me._get_id();
		
		me.superclass.prototype.initDrawing.call(me);
		
		// me.el$.addClass("form-outline");
		me.tl$ && me.tl$.hide();
		me.mp$ = me.createTextField(me.el$, me.property.fieldlabel);
		lbl$ = me.lbl$ = $(".mdc-floating-label", me.mp$);

		me.datefield = $("<input type='text'></input>")
			.css({
				position: "absolute",
				top: 0,
				bottom: 0,
				left: 0,
				width: 0,
				border: 0,
				display: "none"
			})
			.appendTo(me.el$);

		me.mp$.addEventListener("change", function(e) {
			if (me.datefield.val() != me.mp$.value)
				me.datefield.val(me.mp$.value);
		});

		me.mp$ = mdc.textField.MDCTextField.attachTo(me.mp$);
		me.mp$.placeholder = IG$.calendar_locale.c1disp;
		IG$.dateUtil.createDatePicker(me, me.datefield, function(dateText, inst) {
		});

		// me.datefield.setValue(cdate);
		// me.datefield.datepicker("setDate", cdate);
		
		$("<div class='id-db-cal-btn'></div>").appendTo(me.el$).bind("click", function() {
			me.datefield.datepicker("show");
			me._sync_val(me.mp$, me.datefield, 0);
		});
		
		// me.property["text"] = me.getValue();
	},
	
	invalidate: function () {
	},
	
	commit: function() {
		var me = this;
		me.property["text"] = me.getValue();
	},
	
	getValue: function(param) {
		var dt = this.datefield.datepicker("getDate"),
			strdt;
			
		if (dt)
		{
			strdt = dt.format('Ymd');
			param && param.push({code: strdt, value: strdt});
		}
		return strdt;
	}
});

IG$.controls.datechooser = new IG$.ctrlDateField({}, null);