IG$.cVis.boxplot = $s.extend(IG$.cVis._echart, {
	subtype: "boxplot",

	draw: function(mresult) {
		var i,
			j,
			me = this,
			mcr = me.sheetoption ? me.sheetoption.model.chart_option : {},
			data = mresult._tabledata,
			fc = mresult.colfix,
			fr = mresult.rowfix,
			tc = (data.length > 0) ? data[0].length : 0,
			title,
			fields = [],
			matrixdata = [],
			row,
			tn,
			relationgroups = mcr.relationgroups,
			sep = me.getSep();

		var dp = [],
			cols = [],
			cval,
			row,
			mdp = [],
			tmax=0;

	
		/* Convert from tabular format to array of objects. */
		for (i=fc; i < tc; i++)
		{
			for (j=0; j < fr; j++)
			{
					cval = (j==0) ? data[j][i].text : cval + sep + data[j][i].text;
			}
			cols.push(cval);
			mdp.push({id: cval, median: 0, uq: 0, lq: 0, max: 0, min: 0});
		}
	
		for (i=fc; i < tc; i++)
		{
			row = [];
	
			var min=Number(data[fr][i].code),
				max=min,
				sum=0,
				val,
				ui = parseInt((data.length - fr) * .75),
				li = parseInt((data.length - fr) * .25),
				mi = parseInt((data.length - fr) * .5);
	
			for (j=fr; j < data.length; j++)
			{
				if (!data[j][i].code)
					continue;
				val = Number(data[j][i].code);
				sum += val;
				row.push(val);
			}
	
			row = row.sort(function (a, b) { return a-b});
			mdp[i-fc].min = row[0];
			mdp[i-fc].max = row[row.length-1];
			mdp[i-fc].median = row[mi];
			mdp[i-fc].lq = row[li];
			mdp[i-fc].uq = row[ui];
			tmax = Math.max(tmax, max);
			// dp.push(row);
		}

		var mdata =[],
			xticks = [],
			m;
		for (i=0; i < mdp.length; i++)
		{
			// [min,  Q1,  median (or Q2),  Q3,  max]
			m = {
				name: mdp[i].id,
				value: [mdp[i].min, mdp[i].lq, mdp[i].median, mdp[i].uq, mdp[i].max]
			};
			xticks.push(m.name);
			mdata.push(m);
		}

		var option = {
			tooltip: {
				trigger: 'item',
				axisPointer: {
					type: 'shadow'
				}
			},
			
			xAxis: {
				type: 'category',
				boundaryGap: true,
				data: xticks,
				nameGap: 30,
				splitArea: {
					show: false
				},
				splitLine: {
					show: false
				}
			},
			yAxis: {
				type: 'value',
				splitArea: {
					show: true
				}
			},
			series: [
				{
					name: 'boxplot',
					type: 'boxplot',
					data: mdata
				}
			]
		};

		me.adjOption(option);

		me.drawmode = "echart";
		
		me.render([option], mresult);

		return [option];
	}
});