IG$.pageParameter = function(owner, uid, name, value) {
	var me = this;
	
	me.owner = owner;
	me.uid = uid;
	me.name = name;
	me.value = value;
	me.orig_value = value;
	
	me.$rel_params = [];
};

IG$.pageParameter.prototype = {
	set: function(value) {
		var me = this,
			pobj = me.owner.pobj;
		me.value = value;
		
		pobj && pobj.$set_params && pobj.$set_params(me);
	},
	get: function() {
		return this.value;
	},
	val: function(value) {
		var me = this;
		if (typeof value == "undefined")
		{
			return me.get();
		}
		else
		{
			me.set(value);
		}
	},
	validate: function(params) {
		var me = this,
			page_param_map = me.owner.page_param_map,
			n = 0, len,
			i, i2, param,
			v = me.value;
		
		me.orig_value = v;
		me.$rel_params = [];
		
		if (v && v.length)
		{
			len = me.value.length;
			
			i = v.indexOf("${");
			
			while (i > -1)
			{
				i2 = v.indexOf("}", i + 2);
				
				if (i2 < 0)
				{
					break;
				}
				
				param = v.substring(i + 2, i2);
				
				if (param && page_param_map[param] && param != me.name)
				{
					me.$rel_params.push(page_param_map[param]);
				}
				
				i = i2 + 1;
			}
		}
	},
	
	set_param: function(name, value) {
		var me = this,
			v = me.value,
			i, len, vlen,
			k = "${" + name + "}",
			s = "",
			n = 0;
		
		if (v && v.length)
		{
			vlen = v.length;
			len = k.length;
			i = v.indexOf(k);
			
			while (i > -1)
			{
				s = v.substring(n, i) + (value || "");
				n += i + len;
				i = v.indexOf(k, i + len);
				
				if (i + len < 0)
					break;
			}
			
			if (n < vlen)
			{
				s += v.substring(n + vlen);
			}
		}
		
		return s;
	}
};

IG$.frameEvents = function(node) {
	var me = this;
	
	me.type = "actionitem";

	me.inherit = IG$.clEvents;
	me.inherit(node);
}

IG$.frameEvents.prototype = new IG$.clEvents();

IG$.frameControl = function(node, parentctrl, owner) {
	var me = this,
		i,
		ctrl,
		tnode,
		pname, pvalue,
		evnodes,
		snodes,
		npos;
		
	me.properties = {
		visible: true,
		border: 0,
		bordercolor: "#e5e5e5",
		backgroundcolor: "#ffffff",
		padding: 2
	};
	
	me.parentctrl = parentctrl;
	me.position = {};
	me.layout = [];
	me.pname = (parentctrl && parentctrl.name) ? parentctrl.name : null;
	me.puid = (parentctrl && parentctrl.uid) ? parentctrl.uid : null;
	// me.events = [];
	me.actionlist = {};
	me._f_columns = [];
	
	if (node)
	{
		me.uid = node.uid;
		me.type = node.type;
		npos = node.pos;

		$.each("top;left;width;height;right;middle;bottom;percentwidth;percentheight".split(";"), function(i, k) {
			if (npos[k])
			{
				me.position[k] = Number(npos[k]);
			}
		});
		
		tnode = node.properties;
	
		if (tnode)
		{
			for (pname in tnode)
			{
				pvalue = tnode[pname];
				me.properties[pname] = pvalue;
			}
		}
		
		me.name = me.properties["Name"];
		
		//evnodes = IG$.XGetNode(node, "appl/events");
		
		//if (evnodes)
		//{
		//	for (i=0; i < evnodes.length; i++)
		//	{
		//		me.events.push(new IG$.frameEvents(evnodes[i]));
		//	}
		//}
		
		evnodes = node.appl.actevents_items;
		
		if (evnodes)
		{
			for (k in evnodes)
			{
				me.actionlist[k] = evnodes[k];
			}
		}

		evnodes = node.appl.xparam;

		if (evnodes && evnodes.length)
		{
			me._xparam = evnodes;
		}
		
		evnodes = node.appl.f_columns;
		
		if (evnodes)
		{
			me._f_columns = [];
			
			for (i=0; i < evnodes.length; i++)
			{
				var p = evnodes[i];
				me._f_columns.push(p);
			}
		}
		
		tnode = node.appl.item;
		
		if (tnode)
		{
			me.item = tnode;
			owner.regReportContent(me.item, me);
		}
		
		snodes = node.wgt;
		
		if (snodes)
		{
			for (i=0; i < snodes.length; i++)
			{
				ctrl = new IG$.frameControl(snodes[i], me, owner);
				ctrl.updatePropertyValue();
				me.layout.push(ctrl);
				if (owner)
				{
					owner.controls[ctrl.uid] = ctrl;
				}
			}
		}
	}
}

IG$.frameControl.prototype = {
	updatePropertyValue: function(fcreate, pobj) {
		var me = this,
			i, cprop = {}, key,
			dbase = new IG$.clControlItem(null, null, 1, pobj),
			dummy = dbase.getControl(me.type.toLowerCase()),
			position = me.position,
			cs;
		
		for (i=0; i < dummy.p.length; i++)
		{
			cprop[dummy.p[i].name] = dummy.p[i];
		}
		
		for (key in me.properties)
		{
			if (cprop[key])
			{
				value = me.properties[key];
				
				switch (cprop[key].datatype)
				{
				case "boolean":
					if (value && value.length > 0)
					{
						me.properties[key] = (value == "true") ? true : false;
					}
					break;
				case "number":
					if (value && value.length > 0)
					{
						me.properties[key] = Number(value);
					}
					break;
				}
			}
		}
		
		if (fcreate)
		{
			cs = IG$.getControl(me.type, false, true);
			position.width = cs.width;
			position.height = cs.height;
		}
	},
	
	getXML: function() {
		var me = this,
			key,
			actionlist = me.actionlist,
			i,
			r = {
				uid: me.uid,
				name: me.name,
				type: me.type,
				pos: {},
				properties: {},
				appl: {
					item: null,
					actevents_items: {},
					f_columns: []
				}
			},
			sub_widget,
			mpos = me.position;
		
		$.each("top;left;width;height;right;middle;bottom;percentwidth;percentheight".split(";"), function(i, k) {
			r.pos[k] = mpos[k] == null || isNaN(mpos[k]) ? "" : "" + mpos[k];
		});
		
		for (key in me.properties)
		{
			if (me.properties[key] !== null && typeof me.properties[key] != "undefined")
			{
				r.properties[key] = "" + me.properties[key];
			}
		}
	
		if (me.item && me.item.uid)
		{
			r.appl.item = me.item;
		}
				
		for (key in me.actionlist)
		{
			ev = me.actionlist[key];
			r.appl.actevents_items[key] = ev;
		}
		
		if (me._f_columns)
		{
			for (i=0; i < me._f_columns.length; i++)
			{
				r.appl.f_columns.push(me._f_columns[i]);
			}
		}
		
		if (me._xparam)
		{
			r.appl.xparam = me._xparam;
		}
		
		if (me.layout && me.layout.length > 0)
		{
			r.wgt = [];
			
			for (i=0; i < me.layout.length; i++)
			{
				sub_widget = me.layout[i].getXML();
				r.wgt.push(sub_widget);
			}
		}
		
		return r;
	}
}

IG$.cdxml = function(instance, jdoc) {
	var me = this;	
	me.instance = instance,
	me.content = jdoc ? jdoc.content : {};

	if (jdoc)
	{
		me.item = {
			name: jdoc.name,
			uid: jdoc.uid,
			type: jdoc.type,
			nodepath: jdoc.nodepath,
			writable: jdoc.writable
		};
	}
}

IG$.cdxml.prototype = {
	regReportContent: function(item, ctrl) {
		var me = this,
			i,
			tarray = me.dashboardreport,
			citem = {
				uid: item.uid,
				type: item.type,
				nodepath: item.nodepath,
				name: item.name
			};

		if (ctrl)
		{
			if (ctrl.type == "combobox")
			{
				citem._control = ctrl;
				tarray = me.valueset;
			}
		}
			
		for (i=0; i < tarray.length; i++)
		{
			if (tarray[i].uid == citem.uid)
			{
				return;
			}
		}
		
		tarray.push(citem);
	},
		
	parseContent: function(pobj) {
		var me = this,
			instance = me.instance,
			content,
			tnode,
			snodes,
			i, j, bexist, appdata,
			ctrl,
			n, v, u,
			pvar;
		
		content = me.content;
		me.pobj = pobj;

		me.tmpl = null;
		
		$s.apply(me, {
			controls: {},
			eventseq: 0,
			events: {},
			_applActions: {onload: null, ontimer: null},
			activescript: "",
			_funcNames: [],
			dashboardreport: [],
			valueset: [],
			page_params: [],
			page_param_map: {},
			rcs: [],
			cube_objects: []
		});
		
		if (content)
		{
			me.tmpl = content.tmpl;
			
			me.layout = [];
			
			$s.apply(me, {
				autowidth: content.autowidth,
				autoheight: content.autoheight,
				vscroll: content.vscroll,
				hscroll: content.hscroll,
				gridsize: content.gridsize || 12,
				width: content.width || 800,
				height: content.height || 600,
				minwidth: content.minwidth || 500,
				minheight: content.minheight || 500,
				cls: content.cls || "",
				background: content.background || "",
				title: content.title || "",
				cube_objects: content.cube_objects || []
			})
			
			content.wgt = content.wgt || [];
			
			snodes = content.wgt;
			
			for (i=0; i < snodes.length; i++)
			{
				ctrl = new IG$.frameControl(snodes[i], null, me);
				ctrl.updatePropertyValue(undefined, me.pobj);
				me.layout.push(ctrl);
				me.controls[ctrl.uid] = ctrl;
			}
			
			me.activescript = content.activescript;
			
			me._condScript = content.conditionscript;
			
			pobj && me.parseScriptFunc();
			
			tnode = content.page_params;
			
			if (tnode)
			{
				for (i=0; i < tnode.length; i++)
				{
					u = tnode[i].uid || tnode[i].name;
					n = tnode[i].name;
					v = tnode[i].value;
					
					pvar = new IG$.pageParameter(me, u, n, v);
					pvar.type = tnode[i].type || "var";
					pvar.ctrltype = tnode[i].ctrltype;
					me.page_params.push(pvar);
					me.page_param_map[pvar.uid] = pvar;
				}
				
				if (me.page_param_map["userid"])
				{
					me.page_param_map["userid"].value = instance.dlgLogin.logininfo.userid;
				}
				else
				{
					pvar = new IG$.pageParameter(me, "userid", "userid", instance.dlgLogin.logininfo.userid);
					pvar.type = "var";
					me.page_params.push(pvar);
					me.page_param_map[pvar.uid] = pvar;
				}
			}
			
			tnode = content.acteventitems;
			
			if (tnode)
			{
				var evuid,
					mkey,
					fevent,
					gevent;
				
				for (i=0; i < tnode.length; i++)
				{
					gevent = {
						uid: tnode[i].uid,
						name: tnode[i].name,
						type: tnode[i].type,
						description: tnode[i].description
					};
					evuid = tnode[i].uid;

					if (evuid.indexOf("_") > -1)
					{
						mkey = evuid.substring(evuid.lastIndexOf("_") + 1);
						if (mkey != "" && mkey.length > 0)
						{
							me.eventseq = Math.max(me.eventseq, Number(mkey) + 1);
						}
					}

					if (gevent.type == "actiongroup")
					{
						gevent.actitem = [];
						tnode[i].actitem = tnode[i].actitem || [];
						me.events[evuid] = gevent;

						for (j=0; j < tnode[i].actitem.length; j++)
						{
							fevent = new IG$.frameEvents(tnode[i].actitem[j]);
							evuid = tnode[i].actitem[j].uid;
							if (evuid.indexOf("_") > -1)
							{
								mkey = evuid.substring(evuid.lastIndexOf("_") + 1);
								if (mkey != "" && mkey.length > 0)
								{
									me.eventseq = Math.max(me.eventseq, Number(mkey) + 1);
								}
							}
						
							fevent.updateParamValue(me);
							gevent.actitem.push(fevent);
							// me.events[evuid] = fevent;
						}
					}
					else if (gevent.type == "actionitem")
					{
						gevent = new IG$.frameEvents(tnode[i]);
						gevent.updateParamValue(me);
						me.events[evuid] = gevent;
					}
				}
			}
			
			tnode = content.appl_acts_items;
			
			if (tnode)
			{
				for (i in tnode)
				{
					var actuid = i,
						hnodes = tnode[i];
						
					me._applActions[actuid] = [];
					
					for (j=0; j < hnodes.length; j++)
					{
						me._applActions[actuid].push(hnodes[j]);
					}
				}
			}
			
			tnode = content.appl_data;
			
			if (tnode)
			{
				me.applicationdata = [];
				
				for (i=0; i < tnode.length; i++)
				{
					bexist = false;
					appdata = tnode[i];
					
					for (j=0; j < me.applicationdata.length; j++)
					{
						if (me.applicationdata[j].uid == appdata.uid)
						{
							bexist = true;
							break;
						}
					}
					
					if (bexist == false)
					{
						me.applicationdata.push(appdata);
					}
				}
			}
		}
	},
	
	parseScriptFunc: function() {
		ig$._scfunc = ig$._scfunc || 0;
		
		var me = this,
			uid = me.content.uid || ("scfunc_" + ig$._scfunc++),
			txtscript = Base64.decode(me.activescript);
		
		me.mainDynScript = new IG$.cDynScript('cls_' + uid.replace("-", "_"), "IG$.dyn_base");
		me.mainDynScript.loadScript(txtscript);
		me.mainDynScript.preparePrototype(me.controls, me.pobj);
		
		me._funcNames = me.mainDynScript.getFunctionList();
	},
	
	getLayout: function() {
		var me = this,
			i,
			r = {};
		
		$s.apply(r, {
			autowidth: me.autowidth,
			autoheight: me.autoheight,
			vscroll: me.vscroll,
			hscroll: me.hscroll,
			gridsize: me.gridsize || 12,
			width: me.width,
			height: me.height,
			minwidth: me.minwidth,
			minheight: me.minheight,
			title: me.title,
			cls: me.cls,
			background: me.background,
			wgt: []
		});
			
		if (me.layout && me.layout.length > 0)
		{
			for (i=0; i < me.layout.length; i++)
			{
				r.wgt.push(me.layout[i].getXML());
			}
		}
		
		return r;
	},
	
	setLayout: function(value) {
		var me = this,
			jdoc = JSON.parse(value),
			r = false,
			tnode,
			snodes, i,
			ctrl;
		
		if (jdoc)
		{
			tnode = jdoc.wgt;
			
			if (tnode)
			{
				r = true;
				me.layout = [];
				me.controls = {};
				
				for (i=0; i < tnode.length; i++)
				{
					ctrl = new IG$.frameControl(tnode[i], null, me);
					ctrl.updatePropertyValue();
					me.layout.push(ctrl);
					me.controls[ctrl.uid] = ctrl;
				}
			}
		}
		
		return r;
	},
	
	getXML: function() {
		var me = this,
			i,
			events = me.events,
			cnt = me.content,
			key,
			r = {
				uid: cnt.uid,
				name: cnt.name,
				nodepath: cnt.nodepath,
				type: cnt.type
			},
			rec,
			layout;
		
		if (me.tmpl && me.tmpl.uid)
		{
			r.tmpl = me.tmpl;
		}
		
		layout = me.getLayout();
		
		r.autowidth = layout.autowidth;
		r.autoheight = layout.autoheight;
		r.vscroll = layout.vscroll;
		r.hscroll = layout.hscroll;
		r.gridsize = layout.gridsize;
		r.width = layout.width;
		r.height = layout.height;
		r.minwidth = layout.minwidth;
		r.minheight = layout.minheight;
		r.cls = layout.cls;
		r.title = layout.title;
		r.background = layout.background;
		
		r.wgt = layout.wgt;
				
		r.activescript = me.activescript;
		
		r.acteventitems = [];
		
		$.each(events, function(index, action) {
			var e;

			if (action.type == "actiongroup")
			{
				e = {
					name: action.name,
					description: action.description,
					uid: action.uid,
					type: action.type,
					actitem: []
				};
				
				$.each(action.actitem, function(j, aev) {
					e.actitem.push(aev.getXML());
				});
			}
			else if (action.type == "actionitem")
			{
				e = action.getXML();
			}
			
			e && r.acteventitems.push(e);
		});
				
		r.appl_acts_items = {};

		r.cube_objects = me.cube_objects;
		
		for (key in me._applActions)
		{
			if (me._applActions[key])
			{
				r.appl_acts_items[key] = [];
				
				var appact = me._applActions[key];
				
				for (i=0; i < appact.length; i++)
				{
					r.appl_acts_items[key].push({
						uid: appact[i].uid,
						name: appact[i].name,
						description: appact[i].description
					});
				}
			}
		}
		
		r.page_params = [];
		
		for (i=0; i < me.page_params.length; i++)
		{
			r.page_params.push({
				uid: me.page_params[i].uid,
				type: me.page_params[i].type,
				ctrltype: me.page_params[i].ctrltype,
				name: me.page_params[i].name,
				value: me.page_params[i].value
			});
		}
		
		
		r.appl_data = [];
		
		if (me.applicationdata)
		{
			for (i=0; i < me.applicationdata.length; i++)
			{
				rec = me.applicationdata[i];
				r.appl_data.push({
					nodepath: rec.nodepath,
					lastupdatedate: rec.lastupdatedate,
					memo: rec.memo,
					name: rec.name,
					type: rec.type,
					uid: rec.uid
				});
			}
		}
		
		return r;
	}
}

IG$.pluginResults = function(jdoc) {
	this.resultmap = {};
	if (jdoc)
	{
		this.parse(jdoc);
	}
}

IG$.pluginResults.prototype = {
	parse: function(jdoc) {
		var me = this;
		me.resultmap = jdoc || {};
	}
};