IG$.rs_refreshMessages = function (xdoc) {
	var i, thtml, prop, nmax,
		chatsublist = $("#chatsublist"),
		rnode = IG$.XGetNode(xdoc, "/smsg"),
		cnodes = IG$.XGetChildNodes(rnode);
	
	if (cnodes && cnodes.length > 0 && IG$.L_SPPL)
	{
		prop = IG$.XGetAttrProp(cnodes[0]);
		if (prop["msgid"] == IG$.L_SPPL)
		{
			return;
		}
	}
	
	chatsublist.empty();
	chatsublist.append($("<li class='view'><span><a href='javascript:f$7(\"CMD_RSN\")'>Write Message</a></span></li>"));
	
	if (cnodes && cnodes.length > 0)
	{
		nmax = Math.min(5, cnodes.length);
		
		if (IG$.L_SPPL)
		{
			$("#alertstext").text("Messages (New)");
		}
		
		for (i=0; i < nmax; i++)
		{
			// <a href="#" class="delete">X</a>
			prop = IG$.XGetAttrProp(cnodes[i]);
			if (i == 0)
			{
				IG$.L_SPPL = prop["msgid"];
			}
			thtml = "<li><a href='#' class='delete'>X</a><p><span style='color:#0000ff;'>" + (prop["username"] || "") + ": </span><br>" + IG$.XGetTextVal(cnodes[i]) + " <br><span style='color:#4d4d4d; font-size: 0.9em; float: right'>(" + (IG$.getFormattedDate(prop["updatedate"], true) || "") + ")</span></p></li>";
			chatsublist.append($(thtml));
		}
	}
}

