IG$.sortOptionDlg = $s.extend($s.window, {
	
	modal: true,
	region:'center',
	layout: {
		type: 'vbox',
		align: 'stretch'
	},
	
	closable: false,
	resizable:false,
	width: 580,
	height: 440,
	
	_confirm: function() {
		this.commit_f();
		this.callback && this.callback.execute();
		this.close();
	},
	
	init_f: function() {
		var me = this,
			model = me.sheetoption.model,
			sortoption = model.sortoption || {},
			rows = model.rows,
			measures = model.measures,
			i, j, dprow = [], dpmeasure = [],
			sortpartition = me.down("[name=sortpartition]"),
			sortmeasure = me.down("[name=sortmeasure]"),
			sortbyvalue = me.down("[name=sortbyvalue]"),
			sortorder = sortoption.sortorder || [],
			mgrid_src = me.down("[name=mgrid_src]"),
			mgrid_tgt = me.down("[name=mgrid_tgt]"),
			sortitems = [],
			customsort = [],
			si;
			
		dprow.push({
			name: IRm$.r1('B_DEFAULT'),
			uid: "",
			type: "",
			nodepath: ""
		});
		
		for (i=0; i < rows.length; i++)
		{
			dprow.push({
				name: rows[i].name,
				uid: rows[i].uid,
				type: rows[i].type,
				nodepath: rows[i].nodepath
			});
			
			sortitems.push({
				name: rows[i].name,
				uid: rows[i].uid,
				type: rows[i].type,
				nodepath: rows[i].nodepath,
				sortorder: rows[i].sortorder || "",
				memo: (rows[i].memo == "NUMBER" || rows[i].memo == "VARCHAR") ? rows[i].memo : "",
				numeric: rows[i].memo == "NUMBER" ? true : false,
				sorder: (rows[i].sortorder == "asc" ? IRm$.r1("B_ASC") : (rows[i].sortorder == "desc" ? IRm$.r1("B_DSC") : ""))
			});
		}
		
		dpmeasure.push({
			name: IRm$.r1('B_DEFAULT'),
			uid: "",
			type: "",
			nodepath: ""
		});
		
		for (i=0; i < measures.length; i++)
		{
			dpmeasure.push({
				name: measures[i].name,
				uid: measures[i].uid,
				type: measures[i].type,
				nodepath: measures[i].nodepath
			});
		}
		
		for (j=0; j < sortorder.length; j++)
		{
			for (i=sortitems.length -1; i >= 0; i--)
			{
				if (sortitems[i].uid == sortorder[j].uid)
				{
					si = sortitems[i];
					
					si.sortorder = sortorder[j].sortorder || "";
					si.sorder = (si.sortorder == "asc" ? IRm$.r1("B_ASC") : (si.sortorder == "desc" ? IRm$.r1("B_DSC") : ""));
					
					si.memo = sortorder[j].datatype || "";
					si.numeric = si.memo == "NUMBER" ? true : false;
					
					customsort.push(si);
					sortitems.splice(i, 1);
					break;
				}
			}
		}
		
		sortpartition.store.loadData(dprow);
		sortmeasure.store.loadData(dpmeasure);
		
		mgrid_src.store.loadData(sortitems);
		mgrid_tgt.store.loadData(customsort);
			
		me.down("[name=sortmethod]").setValue({
			sm: sortoption.sortmethod || "normal"
		});
		me.down("[name=showlastrank]").setValue(sortoption.showlastrank);
		me.down("[name=sortcount]").setValue(sortoption.sortcount || 5);
		me.down("[name=sortdimname]").setValue(sortoption.sortdimname);
		sortmeasure.setValue(sortoption.sortmeasure);
		sortpartition.setValue(sortoption.sortpartition);
		sortbyvalue.setValue(sortoption.sortbyvalue);
		me.down("[name=sortothervalues]").setValue(sortoption.sortothervalues);
	},
	
	changeSortMethod: function() {
		var sortmethod = this.down("[name=sortmethod]").getValue().sm,
			rankfield = this.down("[name=rankfield]"),
			customfield = this.down("[name=customfield]");
		
		switch (sortmethod)
		{
		case "normal":
			rankfield.setVisible(false);
			customfield.setVisible(false);
			break;
		case "custom":
			rankfield.setVisible(false);
			customfield.setVisible(true);
			break;
		case "top":
		case "bottom":
			rankfield.setVisible(true);
			customfield.setVisible(false);
			break;
		}
	},
	
	commit_f: function() {
		var me = this,
			model = me.sheetoption.model,
			sortoption,
			mgrid_tgt = me.down("[name=mgrid_tgt]").store,
			rows = model.rows, row, uid,
			i, j, sitem = [];
		
		sortoption = model.sortoption = {};
		
		for (i=0; i < mgrid_tgt.data.items.length; i++)
		{
			row = mgrid_tgt.data.items[i];
			uid = row.get("uid");
			
			for (j=0; j < rows.length; j++)
			{
				if (rows[j].uid == uid)
				{
					switch (row.get("sorder"))
					{
					case IRm$.r1("B_ASC"):
						rows[j].sortorder = "asc";
						break;
					case IRm$.r1("B_DSC"):
						rows[j].sortorder = "desc";
						break;
					default:
						rows[j].sortorder = null;
						break;
					}
					
					if (row.get("numeric") == true)
					{
						rows[j].memo = "NUMBER";
					}
					else 
					{
						rows[j].memo = "VARCHAR";
					}
					
					sitem.push({
						uid: rows[j].uid,
						name: rows[j].name,
						datatype: rows[j].memo,
						sortorder: rows[j].sortorder
					});
					break;
				}
			}
		}
		
		sortoption.sortorder = sitem;
		sortoption.sortmethod = me.down("[name=sortmethod]").getValue().sm;
		sortoption.showlastrank = me.down("[name=showlastrank]").getValue();
		sortoption.sortcount = me.down("[name=sortcount]").getValue();
		sortoption.sortmeasure = me.down("[name=sortmeasure]").getValue();
		sortoption.sortpartition = me.down("[name=sortpartition]").getValue();
		sortoption.sortbyvalue = me.down("[name=sortbyvalue]").getValue();
		sortoption.sortdimname = me.down("[name=sortdimname]").getValue();
		sortoption.sortothervalues = me.down("[name=sortothervalues]").getValue();
	},
	
	moveSelections: function(direction) {
		var me = this,
			mgrid_src = me.down("[name=mgrid_" + (direction == 1 ? "src" : "tgt") + "]"),
			mgrid_tgt = me.down("[name=mgrid_" + (direction == 1 ? "tgt" : "src") + "]"),
			sel = mgrid_src.getSelectionModel().selected,
			i, rec;
			
		if (sel && sel.length)
		{
			for (i=0; i < sel.length; i++)
			{
				rec = sel.items[i];
				mgrid_src.store.remove(rec);
				mgrid_tgt.store.add(rec);
			}
		}
	},
	
	changeOrder: function(direction) {
		var me = this,
			mgrid = me.down("[name=mgrid_tgt]"),
			sm = mgrid.getSelectionModel(),
			sel = sm.selected,
			ri, rec;
			
		if (sel && sel.length == 1)
		{
			rec = sel.items[0];
			ri = mgrid.store.indexOf(rec);
			
			if (direction == -1)
			{
				if (ri > 0)
				{
					mgrid.store.remove(rec);
					rec = mgrid.store.insert(ri-1, rec);
					sm.select(rec, true);
				}
			}
			else 
			{
				if (ri+1 < mgrid.store.data.items.length)
				{
					mgrid.store.remove(rec);
					rec = mgrid.store.insert(ri+1, rec);
					sm.select(rec, true);
				}
			}
		}
	},
	
	initComponent : function() {
		this.title = IRm$.r1('L_SORT_OPTION');
		var panel = this;
				 
		$s.apply(this, {
			padding: ig$.padding,
			items: [
				{
					xtype: "panel",
					bodyBorder: false,
					autoScroll: true,
					layout: {
						type: "vbox",
						align: "stretch"
					},
					
					defaults: {
						anchor: "100%"
					},
					
					fieldDefaults: {
						labelWidth: 160
					},
					
					// showlastrank;sortcount;sortmethod;sortmeasure;sortorder;sortpartition
					
					items: [
						{
							xtype: "radiogroup",
							name: "sortmethod",
							fieldLabel: IRm$.r1("L_SORT_SEL"),
							columns: 1,
							labelWidth: 100,
							vertical: true,
							items: [
								{
									boxLabel: IRm$.r1('B_DEFAULT'), name: "sm", inputValue: "normal"
								},
								{
									boxLabel: IRm$.r1("B_CUSTOM"), name: "sm", inputValue: "custom"
								},
								{
									boxLabel: IRm$.r1("L_RANK_TOP"), name: "sm", inputValue: "top"
								},
								{
									boxLabel: IRm$.r1("L_RANK_BOTTOM"), name: "sm", inputValue: "bottom"
								}
							],
							listeners: {
								change: function(field, nvalue, ovalue, eopts) {
									panel.changeSortMethod();
								}
							}
						},
						{
							xtype: "fieldset",
							name: "rankfield",
							border: 0,
							hidden: true,
							flex: 1,
							fieldDefaults: {
								labelWidth: 100
							},
							items: [
								{
									name: "sortcount",
									xtype: "numberfield",
									fieldLabel: IRm$.r1("L_RNK_CNT")
								},
								{
									name: "showlastrank",
									xtype: "checkbox",
									fieldLabel: IRm$.r1("L_RNK_LST")
								},
								{
									name: "sortmeasure",
									fieldLabel: IRm$.r1("L_RNK_VAL"),
									xtype: "combobox",
									queryMode: "local",
									displayField: "name",
									valueField: "uid",
									editable: false,
									autoSelect: true,
									store: {
										fields: [
											"name", "uid", "type", "nodepath"
										]
									}
								},
								{
									name: "sortpartition",
									fieldLabel: IRm$.r1("L_RNK_PAR"),
									xtype: "combobox",
									queryMode: "local",
									displayField: "name",
									valueField: "uid",
									editable: false,
									autoSelect: true,
									store: {
										fields: [
											"name", "uid", "type", "nodepath"
										]
									}
								},
								{
									name: "sortbyvalue",
									fieldLabel: IRm$.r1("L_RNK_SVAL"),
									xtype: "checkbox"
								},
								{
									name: "sortdimname",
									fieldLabel: IRm$.r1("L_RNK_D_NAME"),
									xtype: "textfield"
								}
							]
						},
						{
							xtype: "panel",
							name: "customfield",
							hidden: true,
							border: 0,
							flex: 1,
							layout: {
								type: "hbox",
								align: "stretch"
							},
							items: [
								{
									xtype: "fieldset",
									flex: 1,
									title: IRm$.r1("L_SORT_SRC"),
									layout: "fit",
									items: [
										{
											name: "mgrid_src",
											flex: 1,
											xtype: "gridpanel",
											stateful: true,
											$h: 240,
											border: 1,
											store: {
												fields: [
													"name", "uid", "type", "sortorder", "sorder", "memo", "nodepath"
												]
											},
											selType: "checkboxmodel",
											selModel: {
												checkSelector: ".x-grid-cell"
											},
											viewConfig: {
												plugins: {
													ptype: "gridviewdragdrop",
													dragGroup: "gridDDGroup",
													dropGroup: "gridDDGroup"
												}
											},
											columns: [
												{
													header: IRm$.r1("B_NAME"),
													dataIndex: "name",
													sortable: false,
													hideable: false,
													flex: 1
												},
												{
													header: IRm$.r1("B_TYPE"),
													dataIndex: "type",
													hidden: true,
													sortable: false,
													hideable: false,
													flex: 1
												}
											]
										}
									]
								},
								{
									xtype: "container",
									layout: {
										type: "vbox",
										align: "stretch",
										pack: "center",
										padding: ig$.padding
									},
									items: [
										{
											xtype: "container",
											flex: 1
										},
										{
											xtype: "button",
											iconCls: "ig-btn-dblright",
											handler: function() {
												this.moveSelections(1);
											},
											scope: this
										},
										{
											xtype: "button",
											iconCls: "ig-btn-dblleft",
											handler: function() {
												this.moveSelections(2);
											},
											scope: this
										},
										{
											xtype: "container",
											flex: 1
										}
									]
								},
								{
									xtype: "fieldset",
									flex: 1,
									layout: {
										type: "hbox",
										align: "stretch"
									},
									title: IRm$.r1("L_SORT_ORD"),
									items: [
										{
											name: "mgrid_tgt",
											xtype: "gridpanel",
											stateful: true,
											$h: 240,
											flex: 1,
											selType: "checkboxmodel",
											selModel: {
												checkSelector: ".x-grid-cell"
											},
											store: {
												fields: [
													"name", "uid", "type", "nodepath", "sortorder", "sorder", "memo", "numeric"
												]
											},
											viewConfig: {
												plugins: {
													ptype: "gridviewdragdrop",
													dragGroup: "gridDDGroup",
													dropGroup: "gridDDGroup"
												}
											},
											plugins: [
												{
													ptype: "cellediting",
													clicksToEdit: 1
												}
											],
											seltype: "cellmodel",
											columns: [
												{
													header: IRm$.r1("B_NAME"),
													dataIndex: "name",
													sortable: false,
													hideable: false,
													flex: 1
												},
												{
													header: IRm$.r1("B_TYPE"),
													dataIndex: "type",
													hidden: true,
													sortable: false,
													hideable: false,
													flex: 1
												},
												{
													header: IRm$.r1("B_METHOD"),
													dataIndex: "sorder",
													sortable: false,
													hideable: false,
													width: 60
												},
												{
													header: IRm$.r1("B_NUMERIC"),
													xtype: "checkcolumn",
													dataIndex: "numeric",
													sortable: false,
													hideable: false,
													width: 50
												}
											],
											listeners: {
												cellclick: function(view, td, cellIndex, record, rowIndex, e) {
													var selcolumn = cellIndex;
													
													if (selcolumn == 3)
													{
														switch (record.get("sorder"))
														{
														case "":
															record.set("sorder", IRm$.r1("B_ASC"));
															break;
														case IRm$.r1("B_ASC"):
															record.set("sorder", IRm$.r1("B_DSC"));
															break;
														case IRm$.r1("B_DSC"):
															record.set("sorder", "");
															break;
														}
													}
												}
											}
										},
										{
											xtype: "container",
											layout: {
												type: "vbox",
												align: "stretch",
												pack: "center"
											},
											items: [
												{
													xtype: "container",
													flex: 1
												},
												{
													xtype: "button",
													iconCls: "ig-btn-up",
													handler: function() {
														this.changeOrder(-1);
													},
													scope: this
												},
												{
													xtype: "button",
													iconCls: "ig-btn-down",
													handler: function() {
														this.changeOrder(1);
													},
													scope: this
												},
												{
													xtype: "container",
													flex: 1
												}
											]
										}
									]
								}
							]
						},
						{
							xtype: "fieldset",
							title: IRm$.r1("L_OPTIONS"),
							layout: {
								type: "vbox",
								align: "stretch"
							},
							items: [
								{
									xtype: "textfield",
									fieldLabel: IRm$.r1("L_OTHER_VALUES"),
									name: "sortothervalues"
								}
							]
						}
					]
				}
			],
			buttons:[
				{
					text: IRm$.r1('B_CONFIRM'),
					bodyCls: "ig-btn-confirm",
					handler: function() {
						this._confirm();
					},
					scope: this
				}, {
					text: IRm$.r1('B_CANCEL'),
					handler:function() {
						this.close();
					},
					scope: this
				}
			],
			listeners: {
				afterrender: function(ui) {
					this.init_f();
				}
			}
		});
		
		IG$.sortOptionDlg.superclass.initComponent.apply(this, arguments);
	}
});