IG$.RptConf = $s.extend($s.window, {
	
	modal: true,

	layout: {
		type: 'vbox',
		align: 'stretch'
	},
	
	closable: false,
	resizable: false,
	width: 480,
	height: 520,

	init_f: function() {
		var me = this,
			_rop = me.reportoption._mc,
			sheets = me.sheets,
			sopts = [],
			gsheets = me.down("[name=gsheets]"),
			cubeuid = me.down("[name=cubeuid]"),
			cube_objects,
			copts = [];
			
		if (_rop)
		{
			me.down("[name=ploader]").setValue(_rop.ploader);
			me.down("[name=bulkload]").setValue(_rop.bulkload);
			
			$.each(sheets, function(i, sheet) {
				var s = sheet.sheetoption.model;
				sopts.push({
					sheet_id: sheet.sheet_id,
					name: s.name
				});
			});
			
			gsheets.store.loadData(sopts);
			cube_objects = _rop.cube_objects;
			
			$.each(cube_objects, function(i, cobj) {
				copts.push({
					uid: cobj.uid,
					name: cobj.name
				});
			});
			
			cubeuid.store.loadData(copts);
		}
	},
	
	_confirm: function() {
		var me = this,
			_rop = me.reportoption._mc,
			cubeuid = me.down("[name=cubeuid]"),
			cubemap = {},
			rec,
			i,
			cube_objects;
			
		if (_rop)
		{
			_rop.ploader = me.down("[name=ploader]").getValue();
			_rop.bulkload = me.down("[name=bulkload]").getValue();
			
			for (i=0; i < cubeuid.store.data.items.length; i++)
			{
				rec = cubeuid.store.data.items[i];
				
				cubemap[rec.get("uid")] = 1;
			}
			
			cube_objects = _rop.cube_objects;
			for (i=cube_objects.length-1; i>=0; i--)
			{
				if (!cubemap[cube_objects[i].uid])
				{
					cube_objects.splice(i, 1);
				}
			}
		}
		
		me.callback && me.callback.execute();
		
		me.close();
	},
	
	_scfg: function(rec) {
		var me = this,
			sheets = me.sheets,
			rpt = me.rpt,
			sheet, sheet_id = rec.get("sheet_id");
		
		$.each(sheets, function(i, s) {
			if (s.sheet_id == sheet_id)
			{
				sheet = s;
				return false;
			}
		});
			
		sheet && rpt.showSheetOpt(sheet.sheetindex, sheet, new IG$.callBackObj(me, function() {
			rec.set("name", sheet.sheetoption.model.name);
		}));
	},
	
	initComponent : function() {
		var panel = this;

		$s.apply(panel, {
			title: IRm$.r1("L_RPT_CONF"),
			padding: 0,
			border: 0,
			items: [
				{
					xtype: "panel",
					layout: {
						type: "vbox",
						align: "stretch"
					},
					autoScroll: true,
					padding: ig$.padding,
					items: [
						{
							xtype: "fieldset",
							title: IRm$.r1("B_OPT_LAYOUT"),
							layout: {
								type: "vbox",
								align: "stretch"
							},
							items: [
								{
									name: "ploader",
									fieldLabel: IRm$.r1("L_PG_LOADER"),
									xtype: "checkbox",
									boxLabel: IRm$.r1("B_ENABLED"),
									checked: false
								},
								{
									name: "bulkload",
									fieldLabel: IRm$.r1("L_BULK_LOAD"),
									xtype: "checkbox",
									boxLabel: IRm$.r1("B_ENABLED"),
									checked: false
								}
							]
						},
						{
							xtype: "fieldset",
							title: IRm$.r1("L_SHEETS"),
							layout: "anchor",
							defaults: {
								anchor: "100%"
							},
							items: [
								{
									name: "gsheets",
									xtype: "gridpanel",
									height: 200,
									store: {},
									columns: [
										{ 
											text: IRm$.r1("B_ID"),  
											dataIndex: "sheet_id",
											width: 80
										},
										{ 
											text: IRm$.r1("B_NAME"),  
											dataIndex: "name",
											tdCls: "igc-td-link",
											flex: 1
										},
										{
											xtype: "actioncolumn",
											width: 45,
											items: [
												{
													iconCls: "icon-grid-config",
													handler: function(grid, rindex, cindex, rec) {
														var me = this;
														me._scfg(rec);
													},
													scope: this
												}
											]
										}
									],
									listeners: {
										cellclick: function(tobj, td, cellIndex, record, rowIndex, e) {
											var me = this;
											if (cellIndex == 1)
											{
												me._scfg(record);
											}
										},
										scope: this
									}
								}
							]
						},
						{
							xtype: "fieldset",
							title: IRm$.r1("L_R_ANAL_CUBE"),
							layout: "anchor",
							defaults: {
								anchor: "100%"
							},
							items: [
								{
									name: "cubeuid",
									xtype: "gridpanel",
									height: 200,
									store: {},
									columns: [
										{ 
											text: IRm$.r1("B_NAME"),  
											dataIndex: "name",
											sortable: false,
											hideable: false,
											tdCls: "igc-td-link",
											flex: 1
										},
										{
											xtype: "actioncolumn",
											width: 45,
											items: [
												{
													iconCls: "icon-grid-delete",
													tooltip: IRm$.r1("B_REMOVE"),
													handler: function (grid, rowIndex, colIndex) {
														var me = this;
														if (grid.store.data.items.length < 2)
														{
															IG$.ShowError(IRm$.r1("M_NO_DATA"), me);
															return;
														}
														
														IG$.confirmMessages(null, IRm$.r1("M_CONFIRM_DELETE"), function(e) {
															if (e == "yes")
															{
																grid.store.removeAt(rowIndex);
															}
														});
													},
													scope: this
												}
											]
										}
									]
								}
							]
						}
					]
				}
			],
			buttons:[
				"->",
				{
					text: IRm$.r1('B_CONFIRM'),
					bodyCls: "ig-btn-confirm",
					name: "b_confirm",
					handler: function() {
						this._confirm();
					},
					scope: this
				}, 
				{
					text: IRm$.r1('B_CLOSE'),
					handler:function() {
						this.close();
					},
					scope: this
				}
			],
			listeners: {
				afterrender: function() {
					this.init_f();
				}
			}
		});
		IG$.RptConf.superclass.initComponent.apply(this, arguments);
	}
});



