IG$.dyn_base = function() {
	
}

IG$.dyn_base.prototype = {
	$getctrl: function(name) {
		return this.controls[name];
	}
}

IG$.clControlItem = function(node, uctrl, dsmode, owner) {
	var me = this;
	me.owner = owner;
	me.parentcontrol = null;
	me.subcontrols = [];
	me.position = {top: 10, left:10, right: null, bottom: null, width: 100, height: 100, percentwidth: null, percentheight: null};
	me.dsmode = dsmode;
	
	me.property = {
		visible: "true",
		border: "1",
		bordercolor: "#e5e5e5",
		backgroundcolor: "#ffffff",
		padding: "2"
	};
	// me.events = {};
	me.uctrl = uctrl;
	me.actionlist = {};
	
	if (me.uctrl && me.uctrl.ctrltype == "panel" && me.uctrl.property["layout"] == "border")
	{
		me.property["title"] = me.property["title"] || " ";
	}
	
	if (node)
	{
		me.uid = node.uid;
		me.ctrltype = node.type;
		me.ctrlname = node.name;
		me.actionlist = node.actionlist;
		me.position = node.position || null;
		me.property = node.properties;
		me.control = me.getControl(me.ctrltype.toLowerCase());
		me.control.applicationItem = node.item;
	}
}

IG$.clControlItem.prototype = {
	getSelectionData: function(itemname) {
		var me = this,
			seldata = null;
		
		if (me.control && me.control.getSelectionData) {
			seldata = me.control.getSelectionData(itemname);
		}
		
		return seldata;
	},
	
	disposeContent: function (ui) {
		if (ui.control && typeof ui.control != 'undefined')
		{
			ui.control.disposeContent(ui.control);
			ui.control = null;
		}
	},
	
	getControl: function(ctrltype) {
		var me = this;
		return IG$.getControl.call(me, ctrltype, me.dsmode);
	},
	
	need_invalidate: function() {
		var me = this,
			ulayout;
		
		if (me.uctrl && me.uctrl.ctrltype == "panel")
		{
			ulayout = me.uctrl.property.layout;
			
			if (ulayout == "vbox" || ulayout == "hbox")
				return true;
		}
		
		return false;
	},

	clearInvalid: function() {
		var me = this,
			control = me.control;

		if (control)
		{
			control.clearInvalid && control.clearInvalid();
		}
	},

	markInvalid: function() {
		var me = this,
			control = me.control;

		if (control)
		{
			control.markInvalid();
			if (control.cmp$ && control.cmp$.focus)
			{
				control.cmp$.focus();
			}
		}
	}
}

IG$.getControl = function(ctrltype, dsmode, gsize) {
	var ctrl = null,
		me = this;
		
	if (gsize)
	{
		ctrl = {
			width: 100,
			height: 100
		};
	}
	else
	{
		me.property.instance = me.instance;
		
		switch (ctrltype)
		{
		case "titlelabel":
			ctrl = new IG$.ctrlTitleLabel(me.property, me, dsmode);
			break;
		case "olapreport":
		case "compositereport":
			ctrl = new IG$.ctrlPivotReport(me.property, me, dsmode);
			break;
		case "label":
			ctrl = new IG$.ctrlLabel(me.property, me, dsmode);
			break;
		case "textarea":
			ctrl = new IG$.ctrlTextArea(me.property, me, dsmode);
			break;
		case "picture":
		case "image":
			ctrl = new IG$.ctrlPicture(me.property, me, dsmode);
			break;
		case "button":
			ctrl = new IG$.ctrlButton(me.property, me, dsmode);
			break;
		case "textbox":
			ctrl = new IG$.ctrlTextInput(me.property, me, dsmode);
			break;
		case "datechooser":
			ctrl = new IG$.ctrlDateField(me.property, me, dsmode);
			break;
		case "monthchooser":
			ctrl = new IG$.ctrlMonthField(me.property, me, dsmode);
			break;
		case "combobox":
			ctrl = new IG$.ctrlComboBox(me.property, me, dsmode);
			break;
		case "fieldset":
			ctrl = new IG$.ctrlFieldSet(me.property, me, dsmode);
			break;
		case "panel":
			ctrl = new IG$.ctrlPanel(me.property, me, dsmode);
			break;
		case "treefilter":
			ctrl = new IG$.ctrlTreeFilter(me.property, me, dsmode);
			break;
		case "grid":
			ctrl = new IG$.interactiveGrid(me.property, me, dsmode);
			break;
		case "browser":
			ctrl = new IG$.ctrlBrowserPanel(me.property, me, dsmode);
			break;
		case "sheetfilter":
			ctrl = new IG$.sheetFilter(me.property, me, dsmode);
			break;
		case "tabpanel":
			ctrl = new IG$.ctrlTabPanel(me.property, me, dsmode);
			break;
		case "dashboard":
			ctrl = new IG$.ctrlDashboardPanel(me.property, me, dsmode);
			break;
		case "promptfilter":
			ctrl = new IG$.ctrlPromptFilter(me.property, me, dsmode);
			break;
		case "checkbox":
			ctrl = new IG$.ctrlCheckbox(me.property, me, dsmode);
			break;
		case "pivotfilter":
			ctrl = new IG$.pivotFilter(me.property, me, dsmode);
			break;
		case "pivotdesign":
			ctrl = new IG$.pivotDesign(me.property, me, dsmode);
			break;
		case "fileupload":
			ctrl = new IG$.ctrlFileUpload(me.property, me, dsmode);
			break;
		case "scheduler":
			ctrl = new IG$.ctrlScheduler(me.property, me, dsmode);
			break;
		default:
			ctrl = new IG$.ctrlNullControl(me.property, me, dsmode);
			break;
		}
	
		ctrl.type = ctrltype;
	}
	
	return ctrl;
}

IG$.clEvents = function(node) {
	var me = this,
		snode,
		fnode,
		snodelist,
		i, cf, inode, inodes,
		p, k;
	
	me._raw = node || {};
	
	me.type = "actionitem";
	
	me.controlId = null;
	me.enableoffline = null;
	me.filters = null;
	
	me.params = {
		iparams: {},
		oparams: {}
	};
	
	if (node)
	{
		me.uid = node.uid;
		me.name = node.name;
		me.condition_script = node.condition_script;
		me.description = node.description;
		me.purpose = node.purpose ? node.purpose.toLowerCase() : null;
	
		snode = node.params;
		
		if (snode)
		{
			inode = snode.iparams;
			if (inode)
			{
				for (k in inode)
				{
					p = inode[k];
					me.params.iparams[p.uid] = p;
				}
			}
			
			inode = snode.oparams;
			if (inode)
			{
				for (k in inode)
				{
					p = inode[k];
					me.params.oparams[p.uid] = p;
				}
			}
		}
		
		switch(me.purpose)
		{
		case "onlinereport":
			snode = node.item;
			
			me.item = snode;
			
			if (snode)
			{
				me.controlId = snode.controlid;
			}
			break;
		case "valuelist":
			snode = node.options;
			me.item = node.item;
			if (snode)
			{
				// me.controlId = IG$.XGetAttr(snode, "controlid");
				// me.enableoffline = (IG$.XGetAttr(snode, "enableoffline") === "T") ? true : false;
				// me.usereportcontent = (IG$.XGetAttr(snode, "usereportcontent") === "T") ? true : false;
			}
			break;
		case "execute_script":
			if (node.options)
			{
				me.script = node.options.script;
			}
			break;
		case "servercall":
			if (node.options)
			{
				$s.apply(me, {
					jmodule: node.options.jmodule,
					jmodule_name: node.options.jmodule_name,
					jmethod: node.options.jmethod
				});
			}
			break;
		case "restcall":
			if (node.options) 
			{
				$s.apply(me, {
					rmodule: node.options.rmodule,
					rmodule_name: node.options.rmodule_name,
					rmethod: node.options.rmethod,
					rhttpmethod: node.options.rhttpmethod
				});
			}
			break;
		case "open_dlg":
			if (node.options)
			{
				me.btntype = node.options.btntype;
				me.btnclose = node.options.btnclose;
				me.dlgmsg = node.options.dlgmsg;
				me.dlgtitle = node.options.dlgtitle;
			}
			break;
		case "open_win":
			me.item = node.item;
			if (node.options)
			{
				me.ispopup = node.options.ispopup == "T";
			}
			break;
		case "export":
			if (node.options)
			{
				me.exp_tmpl = node.options.exp_tmpl;
				me.exp_out = node.options.exp_out;
			}
			break;
		case "close":
			if (node.options)
			{
				me.dlgresult = node.options.dlgresult;
			}
			break;
		}
	}
}

IG$.clEvents.prototype = {
	parseFilter: function(node, filter) {
		var me = this;
		
		if (node)
		{
			var fglist = node.subGroups,
				i;

			if (fglist && fglist.length > 0)
			{
				for (i=0; i < fglist.length; i++)
				{
					var tgroup = new IG$.clFilterGroup();
					tgroup.name = fglist[i].name; 
					filter.subGroups.push(tgroup);
					me.parseSubFilter(fglist[i], tgroup);
				}
			}
		}
	},
	
	updateParamValue: function(cdxml) {
		var me = this,
			params = me.params,
			page_param_map = cdxml.page_param_map;
		
		$.each([params.iparams, params.oparams], function(i, pp) {
			$.each(pp, function(k, p) {
				if (p.value)
				{
					p.valuename = page_param_map[p.value] ? page_param_map[p.value].name || "ERR" : "N/A"; 
				}
				else if (p.values)
				{
					
				}
			});
		});
	},
	parseSubFilter: function(fgnode, ugroup) {
		var i, j,
			group,
			sfg,
			sfc,
			me = this;
		
		sfg = fgnode.subGroups;
		sfc = fgnode.subConditions;
		
		if (sfg && sfg.length > 0)
		{
			for (j=0; j < sfg.length; j++)
			{
				var group = new IG$.clFilterGroup();
				group.name = IG$.XGetAttr(sfg[j], "name"); 
				me.parseSubFilter(sfg[j], group);
				ugroup.subGroups.push(group);
			}
		}
		else if (sfc && sfc.length)
		{
			for (j=0; j < sfc.length; j++)
			{
				ugroup.subConditions.push(new IG$.clFilter(sfc[j]));
			}
		}
	},
	
	getXML: function() {
		var me = this,
			i,
			cf,
			r = {
				purpose: me.purpose,
				type: me.type,
				uid: me.uid,
				name: me.name,
				condition_script: me.condition_script,
				description: me.description,
				options: {},
				params: {
					iparams: me.params.iparams,
					oparams: me.params.oparams
				}
			},
			purpose = me.purpose,
			options = r.options,
			t;
		
		switch(purpose)
		{
		case "onlinereport":
			r.item = me.item;
			break;
		case "valuelist":
			options.controlid = me.controlId;
			options.enableoffline = me.enableoffline ? "T" : "F";
			r.item = me.item;
			break;
		case "execute_script":
			options.script = me.script;
			break;
		case "servercall":
			options.jmodule_name = me.jmodule_name;
			options.jmodule = me.jmodule;
			options.jmethod = me.jmethod;
			break;
		case "restcall":
			options.rmodule_name = me.rmodule_name;
			options.rmodule = me.rmodule;
			options.rmethod = me.rmethod;
			options.rhttpmethod = me.rhttpmethod;
			break;
		case "open_dlg":
			options.btntype = me.btntype;
			options.btnclose = me.btnclose;
			options.dlgtitle = me.dlgtitle;
			options.dlgmsg = me.dlgmsg;
			break;
		case "export":
			options.exp_tmpl = me.exp_tmpl;
			options.exp_out = me.exp_out;
			break;
		case "open_win":
			options.ispopup = me.ispopup ? "T" : "F";
			r.item = me.item;
			break;
		case "close":
			options.dlgresult = me.dlgresult || "OK";
			break;
		}
		
		return r;
	}
}

