/******************************************************************
	control : pivot design component
 ******************************************************************/
IG$.pivotDesignBase = $s.extend(IG$.v$pnl, {
	layout: {
		type: "vbox",
		align: "stretch"
	},
	
	updateProperty: function(kname, value) {
		var me = this,
			pivotbrowser = me.down("[name=pivotbrowser]"),
			pivoteditor = me.down("[name=pivoteditor]"),
			_cinfo = me._cinfo;
		
		switch(kname)
		{
		case "report_control":
			break;
		case "text":
			break;
		case "selectionmode":
			break;
		case "show_custom_forumula":
			pivotbrowser.down("[name=custom_formula]").setVisible(value);
			break;
		case "show_viewmode":
			pivoteditor.down("[name=dataquerymode_bar]").setVisible(value);
			break;
		case "show_filter":
			pivoteditor.down("[name=btn_filter]").setVisible(value);
			break;
		case "show_advaned_options":
			pivoteditor.down("[name=btn_adv]").setVisible(value);
			break;
		}
	},
	
	_init: function() {
		var me = this,
			pivoteditor = me.down("[name=pivoteditor]");
		
		pivoteditor.down("[name=btn_pagefilter]").setVisible(false);
		pivoteditor.down("[name=btn_grid_style]").setVisible(false);
		pivoteditor.down("[name=sync_view]").setVisible(false);
		
		pivoteditor.on("join_tables", function(fitems) {
				var me = this,
					browser = me.down("[name=pivotbrowser]");
				
				browser.setFilter(fitems);
			}, me
		);
		
		me.applyApplication();
	},
	
	applyApplication: function(jdoc) {
		var me = this,
			pe = me.down("[name=pivoteditor]"),
			pb = me.down("[name=pivotbrowser]"),
			sindex = me.sindex || 0,
			sop,
			appItem = me.applicationItem,
			rop = me.reportoption;
		
		if (!appItem)
			return;
			
		if (!jdoc && appItem.type == "Report" && appItem.uid)
		{
			var req = new IG$._rpc$();
			req.init(me, 
				{
					ack: "content",
					payload: {uid: appItem.uid},
					mbody: {}
				}, me, function(jdoc) {
					me.applyApplication(jdoc);
				}, false);
			req.send();
			return;
		}
		
		if (!rop)
		{
			if (!jdoc) 
			{
				jdoc = {
					type: "Report",
					writable: true,
					manage: true,
					content: {
						cube_objects: [], 
						type: "Report",
						meta_type: me.meta_type || "report",
						writable: true,
						manage: true,
						objinfo: {reportversion: "1.2"},
						ctrls: {
							dock_0: {
								objtype: "_dc",
								layoutinfo: {},
								docid: "dock_0"
							}
						},
						sheets: [
							{
								objtype: "SHEET",
								layoutinfo: {
									docid: "dock_1"
								}
							}
						],
						layout: {
							type: "mondrian",
							children: [
								{
									docid: "dock_0",
									objtype: "_dc",
									width: 400,
									height: 300,
									r: null,
									p: null,
									d: 0,
									children: [
										{
											docid: "dock_1",
											objtype: "SHEET",
											width: 400,
											height: 300,
											r: "dock_0",
											p: null,
											d: 0
										}
									]
								}
							]
						}
					}
				};
			}
			rop = me.reportoption = new IG$.clReports(jdoc, jdoc.content.meta_type);
			
			sop = new IG$.clReport({}, rop.itemtype, false);
			rop.sheets.push(sop);
		}
		
		sop = rop.sheets[sindex];
		
		if (appItem.type == "Bobject")
		{
			rop.cube_objects.push(appItem);
		}
		
		pe.activeSheet = sindex,
		pe.reportoption = me.reportoption;
		pe.sheetoption = sop;
		
		setTimeout(function() {
			pb.loadSheetOption.call(pb, me.reportoption.sheets[me.activeSheet], me.reportoption);
			pe.applCurPivotInfo.call(pe);
			pe._c = 1;
		}, 20);
	},
	
	confirm: function() {
		var me = this,
			pe = me.down("[name=pivoteditor]"),
			sop;

		if (pe._confirm)
		{
			pe._confirm.call(pe);
		}
	},
	
	initComponent : function() {
		var me = this;
		
		$s.apply(this, {
			items: [
				{
					xtype: "panel",
					layout: "card",
					name: "mcard",
					flex: 1,
					items: [
						{
							xtype: "panel",
							layout: "border",
							items: [
								new IG$.p$PivotBrws({
									instance: me.instance,
									name: "pivotbrowser",
									region: "center",
									flex: 1,
									border: 0,
									resizable: true,
									rptptr: me.rptptr,
									callback: new IG$.callBackObj(me, me.updatePivotContent),
									listeners: {
										cube_changed: function(tobj, ev) {
										},
										scope: this
									}
								}),
								new IG$.c$pivotPnl({
									instance: me.instance,
									name: "pivoteditor",
									layoutmode: "panel",
									hidden: false,
									region: "east",
									flex: 3,
									split: true,
									resizable: true,
									_pivotEdtMd: true,
									border: 0
								})
							]
						}
					],
					bbar: [
						"->",
						{
							xtype: "button",
							text: IRm$.r1("L_EXECUTE"), // "Execute",
							handler: function() {
								var me = this,
									pctrl = me.pctrl;
								
								me.confirm();
								pctrl._execRptReq();
							},
							scope: this
						}
					]
				}
			]
		});
		
		me.on("afterrender", me._init);
		
		IG$.pivotDesignBase.superclass.initComponent.apply(this, arguments);
	}
});

IG$.pivotDesign = IG$.extend(IG$.ctrlBase, {
	type: "pivotdesign",
	initComponent: function() {
		var me = this;
		me.activeIndex = 0;
		me.p.push(
			{name: "request_run", type: "event"},
			{name: "flexHeight", type: "property", datatype: "number", value: 0},
			{name: "minHeight", type: "property", datatype: "number", value: 0},
			{name: "show_custom_forumula", type: "property", datatype: "boolean"},
			{name: "show_cluster", type: "property", datatype: "boolean"},
			{name: "show_viewmode", type: "property", datatype: "boolean"},
			{name: "show_filter", type: "property", datatype: "boolean", value: true},
			{name: "show_custom_field", type: "property", datatype: "boolean", value: true},
			{name: "show_advaned_options", type: "property", datatype: "boolean", value: false}
		);
		
		me.superclass.prototype.initComponent.call(me);
	},
	
	processEvent: function(evttype, obj) {
	},

	invalidate: function () {
		var me = this,
			viewer = me.viewer;
			
		viewer && viewer.$ex.adjust();
	},
	
	initDrawing: function () {
		var me = this;

		if (!me.viewer)
		{
			me.viewer = new IG$.pivotDesignBase({
				renderTo: me.el$,
				ctrl: me.ctrl,
				pctrl: me,
				autofit: true,
				header: false,
				move: false,
				applicationItem: me.applicationItem
			});
		}
		
		me.tl$.hide();
		me.__pcinit();
	},

	updateProperty: function(kname, value) {
		var me = this,
			viewer = me.viewer;
		
		viewer.updateProperty(kname, value);
	},
	
	applyApplication: function () {
		var me = this,
			viewer = me.viewer;
		
		if (viewer)
		{
			viewer.applicationItem = me.applicationItem;
			viewer.applyApplication();
		}
	},
	
	updateLayout: function() {
		var me = this,
			dashboard = me.ctrl.dashboard;
	},
	
	_execRptReq: function() {
		var me = this;
		
		me.triggerEvent("request_run");
	},
	
	getSelectionData: function(param) {
		var me = this,
			filteritems,
			i, j,
			viewer = me.viewer,
			berr = [],
			fitem,
			bs,
			rval = [],
			value,
			sel, rec;

		if (param && param.name && viewer)
		{
			sel = viewer.getSelectionModel().selected;
			
			if (sel && sel.length)
			{
				rec = sel.items[0];
				value = rec.get(param.name);
				value && rval.push({code: value, value: value});
			}
		}

		return rval;
	}
});

IG$.controls.pivotdesign = new IG$.pivotDesign({}, null);