IG$.sessionUtils = function(config) {
	var me = this;
	me.instance = config.instance;
};

IG$.sessionUtils.prototype = {
	doStartSession: function(){
		var instance = this.instance,
			panel = instance.dlgLogin,
			uform = $("#loginform"),
			userid = uform.items.items[0].getValue(),
			passwd = uform.items.items[1].getValue();
		
		panel.initProcLogin(instance, userid, passwd);
	},
	
	getKeyPairFunc: function(bg, mts, callback) {
		var panel = this;
		if (bg)
		{
			bg.show();
		}
		
		var panel = this,
			instance = panel.instance,
			lreq = new IG$._rpc$();
			
		lreq.init(panel,
			{
				ack: "security",
				payload: {mts: mts || ""},
				mbody: {}
			}, panel, function(item) {
				var p1 = item.p1,
					p2 = item.p2;
				
				if (p1 && p2)
				{
					instance.rsaPublicKeyModules = p1;
					instance.rsaPublicKeyExpoenent = p2;
					instance.rsa_kinfo = item.p3;
					IG$._g$a = item.mts;
					
					callback && callback.execute(1);
				}
				else if (bg)
				{
					callback && callback.execute();
					bg.hide();
					void 0;
				}
			}, function(jdoc) {
				var msg = jdoc.errormsg || "Error while connecting server";
				bg && bg.hide();
				callback && callback.execute();
				void 0;
				return false;
			});
	
		lreq.send();
	},
	
	getKeyPair: function(userid, passwd, bg, mts, callback, sso_module) {
		var panel = this;
		
		panel.getKeyPairFunc(bg, mts, new IG$.callBackObj(panel, function(success) {
			if (success)
			{
				setTimeout(function() {
					panel.initProcLogin(panel.instance, userid, passwd, bg, mts, callback, sso_module);
				}, 10);
			}
		}));
	},

	val2FA: function(key, bg, mts, callback, sso_module) {
		var me = this,
			instance = me.instance,
			req = new IG$._rpc$();
		
		req.init(me, 
			{
				ack: "twoway_auth",
				payload: {vkey: key, sso_module: sso_module, keyvar: instance.rsa_kinfo},
				mbody: {}
			}, me, me.rdoStartSession, function(xdoc) {
				var r;
				var login_form = $("#login_form" + instance.id);
				var inputs = $("input", ".twoway_key_holder", "#twoway_form", login_form);
				inputs.val("");
				inputs && inputs.length && inputs[0].focus();
				
				if (callback)
					r = callback.execute(xdoc);
				
				if (bg)
				{
					bg.hide();
				}
				
				return r;
			}, bg);
		req.send();
	},
	
	initProcLogin: function(instance, userid, passwd, bg, mts, callback, sso_module) {
		var panel = this,
			instance = panel.instance,
			req = new IG$._rpc$();
		
		var encpwd = IG$.encryptKey(instance, [userid, passwd]);
		// passwd = encpwd.toString(CryptoJS.enc.Hex);
		req.init(panel, 
			{
				ack: "login",
				payload: {userid: encpwd[0], passwd: encpwd[1], sso_module: sso_module, keyvar: instance.rsa_kinfo},
				mbody: {lang: useLocale, mts: mts || "", app: '', session_expire: ("" + ig$.session_expire) || "0"}
			}, panel, panel.rdoStartSession, function(xdoc) {
				var r;
				
				if (callback)
					r = callback.execute(xdoc);
				
				if (bg)
				{
					bg.hide();
				}
				
				return r;
			}, bg);
		req.send();
	},
	
	rdoStartSession: function (jdoc, bg) {
		var panel = this;
		
		var root = jdoc,
			ltoken = root.token,
			instance = panel.instance,
			nuid = root.uid,
			cuser = false,
			lastlogin = root;
		
		if (!IG$._g$a)
		{
			IG$._g$a = jdoc.mts;
		}
		
		if (instance.dlgLogin)
		{
			instance.dlgLogin.lastLogin = lastlogin;
			
			if (instance.mainPanel && instance.mainPanel.updateLoginInfo)
			{
				instance.mainPanel.updateLoginInfo();
			}
		}
		
		if (bg)
		{
			bg.hide();
		}
		
		if (jdoc.twoway_auth == "T")
		{
			$("#login_path").hide();
			$("#twoway_form").show();

			// $("#twoway_key" + instance.id, "#twoway_form").focus();
			var inputs = $("input", ".twoway_key_holder", "#twoway_form");
			inputs.val("");
			inputs && inputs.length && $(inputs[0]).focus();
			return;
		}
				
		if (panel.uuid && panel.uuid.length > 0 && nuid && panel.uuid != nuid)
		{
			cuser = true;
		}
		
		// JIRA#66 issue on new user login need screen refresh
		if (cuser)
		{
			window.location.reload(false); 
		}
		else
		{
			panel.uuid = nuid;
			
			if (ltoken && panel.uuid)
			{
				panel.closeLoginProc(cuser);
			}
		}
	},
	
	closeLoginProc: function(changeuser) {
		this.getUserDetail(changeuser);
	},
	
	finalLoginProc: function() {
		var me = this,
			l3 = me.logininfo.l3.substring(1),
			mechanlevel = $("#mechanlevel");
				
		if (mechanlevel && mechanlevel[0])
		{
			setTimeout(function() {
				switch (l3)
				{
				case "1":
					mechanlevel.attr("title", "Your license is limited using all features.");
					mechanlevel.animate({width: 45}, 2000);
					
					mechanlevel.bind("click", function() {
						window.open("http://www.amplixbi.com/", "_new");
					});
					break;
				case "2":
					mechanlevel.attr("title", "Your license is limited using all features.");
					mechanlevel.animate({width: 60}, 2000);
					mechanlevel.css({backgroundColor: "#0000ff"});
					mechanlevel.bind("click", function() {
						window.open("http://www.amplixbi.com/", "_new");
					});
					break;
				case "3":
				case "4":
					mechanlevel.attr("title", "Currently using full feature and unlimited version.");
					mechanlevel.animate({width: 100}, 2000);
					mechanlevel.css({backgroundColor: "#00ff00"});
					break;
				}
			}, 200);
		}
		
		if (IG$._amplix_ready$ && IG$._amplix_ready$.length)
		{
			$.each(IG$._amplix_ready$, function(i, f) {
				f.apply(null);
			});
			
			IG$._amplix_ready$ = null;
		}

		if (me.callback)
		{
			setTimeout(function() {
				me.callback.execute();
			}, 100);
		}
	},
	
	getUserDetail: function(changeuser) {
		var panel = this,
			req = new IG$._rpc$();
		req.init(panel, 
			{
				ack: "usercontent",
				payload: {address: "/user"},
				mbody: {option: "_gi_", uid: panel.uuid, tmpl: (IG$.__ep ? "sys_print_mode" : IG$.__ep_ || "")}
			}, panel, panel.rs_getUserDetail, null, [changeuser]);
		req.send();
	},
	
	rs_getUserDetail: function(jdoc, params) {
		var me = this,
			instance = me.instance,
			changeuser = params[0],
			desktop;
		
		var userinfo = new IG$._c$session(jdoc.userdetail);
		me.logininfo = userinfo;
		me.jS2 = me.logininfo.hasDutyUID(IG$.dutymap[1], 'A');
		me.desktopsetting = jdoc.desktopinfo;

		if (!IG$.__websocket)
		{
			IG$.__websocket = null;
		}
		
		if (!IG$.__websocket && ig$.$l_m && IG$._source == "framework" && ig$.enable_websocket) // ig$.$l_ < 5 && 
		{
			var url = window.location.href,
				arr = url.split("/"),
				surl = "",
				protocol = "ws",
				i;
			
			if (arr[0].toLowerCase() == "https:")
			{
				protocol = "wss";
			}
			
			for (i=2; i < arr.length-1; i++)
			{
				if (arr[i] == "launcher")
					break;
				
				surl += (i > 2 ? "/" : "") + arr[i];
			}
			
			IG$.__websocket = new IG$._ws({
				protocol: protocol,
				url: surl,
				userdetail: jdoc.userdetail
			});
		}
		
		ig$.features = userinfo.features;
		ig$.delivery_channels = userinfo.delivery_channels || [];
		ig$.ai_provider = userinfo.ai_provider;
		
		ig$.custom_charts = {};

		IG$.__chartoption.charttype = IG$.__chartoption.charttype || [];

		if (userinfo.custom_charts)
		{
			for (i=0; i < userinfo.custom_charts.length; i++)
			{
				var rec = userinfo.custom_charts[i]
					rprop = rec.attributes ? rec.attributes.attrb2 : null;

				if (!rprop)
					continue;

				var rs = rprop.split(";");

				var cchart = {
					label: rs[0],
					charttype: rs[1],
					subtype: rs[2],
					img: rs[3],
					grp: rs[4],
					is_custom: true,
					uid: rec.uid
				};

				ig$.custom_charts[cchart.subtype] = cchart;

				IG$.__chartoption.charttype.push(cchart);
			}
		}
		
		$.cookie("lui", userinfo.userid, {
			expires: 7,
			path: "/"
		});
		
		IG$.$loadApp && IG$.$loadApp(me.instance, userinfo.tmpl, userinfo.fm);
		
		if (changeuser == true)
		{
			IG$.showHideAllWindow(me.instance, true);
			$('#win-mask').css({display: 'none'});
			
			if (instance.mainPanel)
			{
				instance.mainPanel.initRecentVisit();
			}
		}

		if (userinfo.twofa_available && !userinfo.twofa)
		{
			IG$.procMenuCommand && IG$.procMenuCommand(instance, "CMD_PASSWORD_CHANGE", {
				option: "2fa"
			});
		}
		
		if (instance.mainPanel)
		{
			instance.mainPanel.updateLoginInfo();
		}

		me.finalLoginProc();
	}
};

IG$.dutymap = {
	1: "4fce8d2e-6d5144d0",
	2: "0122483f-0155fb4d",
	3: "0125a1a8-01d413a0"
};

IG$._c$session = function (userdetail) {
	var me = this,
		st = [],
		isadmin = false,
		i, p, // j, k, pk, 
		tmpl, tobj,
		calendar_locale,
		duty;
		// mainview,
		// nname;

	calendar_locale = IG$.calendar_locale = IG$.calendar_locale || {};
	
	p = userdetail;
	me.sid = p.sid;
	me.gid = p.gid;
	me.userid = p.id;
	me.username = p.name;
	me.email = p.email;
	me.l3 = p.l3;
	me.l4 = p.l4 == "Y";
	me.auth = [];
	me.authmap = {};
	me.authmap_uid = {};
	me.features = {};
	me.pdffonts = [];
	me.mts = p.mts;
	me.mts_name = p.mts_name;
	me.tmpl = {};
	me.dfrm = p.dfrm;
	me.delivery_channels = p.delivery_channels;
	me.custom_charts = p.custom_charts;
	me.ai_provider = p.ai_provider;
	me.twofa = p.twofa;
	me.twofa_available = p.twofa_available;
	me.twofa_option = p.twofa_option;
	
	calendar_locale.c1disp = p.c1disp;
	calendar_locale.c1format = p.c1format;
	calendar_locale.c2disp = p.c2disp;
	calendar_locale.c2format = p.c2format;
	
	if (me.dfrm && me.dfrm.indexOf(" ") > 0)
	{
		me.dfrm_short = me.dfrm.substring(0, me.dfrm.indexOf(" "));
	}
	else
	{
		me.dfrm_short = "yyyy-mm-dd";
	}
	
	if (p.a2 && !ig$.theme_id)
	{
		ig$.theme_id = p.a2;
	}
	
	tmpl = p.template;

	if (ig$.application_title)
	{
		document.title = ig$.application_title; 
	}

	$("#logo_txt").html(ig$.application_title_html || ig$.application_title);
	
	if (tmpl && tmpl.view)
	{
		child = tmpl.view;
		me.tmpl.mainview = {};
		for (i=0; i < child.length; i++)
		{
			tobj = child[i];
			if (tobj.html)
			{
				var copytext = "&copy; 2005-" + (new Date()).getFullYear() + " amplixbi.com. <br />ALL RIGHTS RESERVED. <br />amplix. Confidential Information";
				tobj.html = IG$.replaceAll(tobj.html, "$APP_NAME", ig$.application_title_html || ig$.application_title || ig$.appname);
				tobj.html = IG$.replaceAll(tobj.html, "$APP_COPY", copytext);
			}
			me.tmpl.mainview[tobj.name] = tobj;
		}
	}
	
	p.duties = p.duties || [];
	me.auth = p.duties;
	
	for (i=0; i < p.duties.length; i++)
	{
		duty = p.duties[i];
		duty.uid = duty.uid || duty.sid;
		me.authmap[duty.name.toLowerCase()] = duty;
		me.authmap_uid[duty.uid.toLowerCase()] = duty;
	}
	
	isadmin = me.authmap_uid[IG$.dutymap[1]] ? true : false;
	
	if (p.features)
	{
		for (i in p.features)
		{
			me.features[i] = (p.features[i].hide === true);
		}
	}
	
	if (p.fonts)
	{
		for (i=0; i < p.fonts.length; i++)
		{
			me.pdffonts.push(p.fonts[i] + ";");
		}
	}
	
	ig$.fmcss && ig$.fmcss.remove();

	// ig$.$l_ = ig$.$l_ || 0; 
	
	st.push("<style type='text/css'>");
	$.each(me.features, function(t, f) {
//		!(isadmin && (f.cls == "ig_mngr" || f.cls == "ig_sys" || f.cls == "ig_ft")) && 
//		st.push("." + f.cls + " { display: none; }");
		
		if (t == "ig_mngr" || t == "ig_ft")
		{
			if (!isadmin)
			{
				st.push("." + t + " { display: none; }");
			}
			/*
			else if (t == "ig_ft" && ig$.$l_ > 5)
			{
				st.push("." + t + " { display: none; }");
			}
			*/
		}
		else if (f == true)
		{
			st.push("." + t + " { display: none; }");
		}
	});
	st.push("</style>");
	
	ig$.fmcss = $(st.join("")).appendTo($("head"));
	
	me.themes = [];
	
	if (p.themes)
	{
		for (i=0; i < p.themes.length; i++)
		{
			me.themes.push({
				name: p.themes[i]
			});
		}
		
		if (window.app_themes)
		{
			try
			{
				window.app_themes(me.themes);
			}
			catch (e)
			{
			}
		}
	}
}

IG$._c$session.prototype = {
	hasDutyUID: function(uid, type) {
		var me = this,
			i;
		
		for (i=0; i < me.auth.length; i++)
		{
			if ((!type || (type && me.auth[i].dutytype == type)) && me.auth[i].uid.toLowerCase() == uid)
			{
				return true;
			}
		}
		
		return false;
	},
	
	hasDutyName: function(name, type) {
		var me = this,
			i;
		
		for (i=0; i < me.auth.length; i++)
		{
			if ((!type || (type && me.auth[i].dutytype == type)) && me.auth[i].name.toLowerCase() == name)
			{
				return true;
			}
		}
		
		return false;
	}
}

