IG$.d$PscrEdit = $s.extend($s.window, {
	title: "Script",
	layout: "fit",
	height: 600,
	width: 750,
	modal: true,
	draggable: true,
	resizable: true,
	focusOnToFront: true,
	bodyPadding: 6,
	
	initApp: function() {
		var me = this,
			reditor = me.down("[name=rscript]"),
			rprompt = me.down("[name=rprompt]"),
			sheetoption = me.sheetoption.model;
			
		reditor.setValue(sheetoption.python_script);
		// rprompt.setValue(roption.rprompts);
		// minwidth.setValue(roption.minwidth);
		// minheight.setValue(roption.minheight);
	},
	
	confirm: function() {
		var me = this,
			reditor = me.down("[name=rscript]"),
			rprompt = me.down("[name=rprompt]"),
			sheetoption = me.sheetoption.model;
			
		sheetoption.python_script = reditor.getValue();

		me.callback && me.callback.execute();
		me.close();
		// rprompt.setValue(roption.rprompts);
	},
	
	initComponent: function() {
		var me = this;
		
		$s.apply(me, {
			items: [
				{
					xtype: "container",
					layout: {
						type: "vbox",
						align: "stretch"
					},
					bodyPadding: 6,
					items: [
						{
							xtype: "tabpanel",
							name: "meT",
							activeTab: 0,
							flex: 1,
							headerPosition: "right",
							tabPosition: "top",
							preventHeader: true,
							border: 0,
							layout: "fit",
							items: [
								{
									xtype: "panel",
									title: "Script",
									layout: {
										type: "vbox",
										align: "stretch"
									},
									border: 0,
									items: [
										{
											xtype: "textarea",
											grow: false,
											flex: 1,
											name: 'rscript',
											fieldLabel: IRm$.r1("L_RSCRIPT"),
											hideLabel: true,
											anchor: '100%'
										}
									]
								},
								{
									xtype: "panel",
									title: "Prompt",
									layout: "fit",
									border: 0,
									items: [
										{
											xtype: "textarea",
											grow: false,
											name: "rprompt",
											fieldLabel: IRm$.r1("L_R_PROMPT"), // "R Prompt",
											hideLabel: true,
											anchor: "100%"
										}
									]
								}
							]
						}
					]
				}
			],
			//constrainHeader: true
			listeners: {
				afterrender: function() {
					this.initApp();
				},
				scope: this
			},
			
			buttons: [
				"->",
				{
					xtype: "button",
					text: IRm$.r1("B_REQUEST"),
					handler: function() {
						var me = this;

						me.confirm();
					},
					scope: this
				},
				{
					xtype: "button",
					text: IRm$.r1("B_CLOSE"),
					handler: function() {
						var me = this;
						me.close();
					},
					scope: this
				}
			]
		});
		
		IG$.d$PscrEdit.superclass.initComponent.call(this);
	}
});

IG$.v$pyViewer = $s.extend(IG$.v$pnl, {
	sheetobj: null,
	pg: 0,
	pgm: -1,
	pgs: 2000,
	rt: -1,
	df: 6,
	
	sized: true,
	aftsized: false,
	
	layout: "fit",
	
	_init: false,
	
	applyReportResult: function(mresults, olapset, reportoption, sheetoption, lrender) {
		var me = this,
			w, h,
			i;
		
		if (!lrender)
		{
			me.mresults = mresults;
			me.olapset = olapset;
			me.reportoption = reportoption;
			me.sheetoption = sheetoption;
		}
		
		if (!me._init)
		{
			return;
		}
		
		w = me.getWidth();
		h = me.getHeight();
		
		setTimeout(function() {
			if (mresults.r_python)
			{
				me.rs_reqPython(mresults.r_python);
			}
			else if (me.sized == true)
			{
				var scripts = ig$.bootconfig.scmap.nbt;
				
				if (!window.requirejs || !window.require)
				{
					IG$.getScriptCache(scripts, new IG$.callBackObj(this, function() {
						me.reqPython();
					}));
				}
				else
				{
					me.reqPython();
				}
			}
		}, 10);
	},
	
	reqPython: function() {
		var me = this,
			olapset = me.olapset,
			reportoption = me.reportoption,
			sheetobj = me.sheetobj,
			doc;

		me.execution_count = 0;
		me._process_executed = 0;
		
		if (olapset && olapset.jobid)
		{
			sheetobj.sheetoption.panelwidth = IG$.j$ext._w(me._parentdom);
			sheetobj.sheetoption.panelheight = IG$.j$ext._h(me._parentdom);
			doc = reportoption.getCurrentPivot();
			
			me.customLoad(true, true);
			
			var req = new IG$._rpc$();
			req.init(me, 
				{
					ack: "olapservice",
					payload: {
						uid: reportoption.uid,
						jobid: olapset.jobid,
						option: "jupyter_script",
						active: "" + sheetobj.sheetindex,
						pivotresult: "F",
						pythonresult: "T"
					},
					mbody: doc,
					meta_type: me.meta_type || "report"
				}, me, function(jdoc) {
					var me = this,
						rg = me.down("[name=rg]"),
						region = $(".notebook", rg.body.dom),
						session_id = jdoc.session_id;
					
					region.empty();
					me.region = region;
					me.execution_count = jdoc.execution_count;
					
					me.session_id = session_id;
					
					if (session_id)
					{
						// websocket
						var ipt_location;
						ipt_location = IG$._ipt_location = IG$._ipt_location || {};
						ipt_location[session_id] = me;
					}
					
					var req = new IG$._rpc$();
					req.init(me, 
						{
							ack: "olapservice",
							payload: {
								uid: reportoption.uid,
								jobid: olapset.jobid,
								option: "pivot",
								active: "" + sheetobj.sheetindex,
								pivotresult: "F",
								pythonresult: "T",
								session_id: session_id
							},
							mbody: doc,
							meta_type: me.meta_type || "report"
						}, me, me.rs_reqPython);
					req.send();
				}
			);
			req.send();
		}
	},
	
	rs_reqPython: function(jdoc) {
		var me = this,
			output,
			rg = me.down("[name=rg]"),
			region = $(".notebook", rg.body.dom);
		
		output = jdoc ? jdoc.execute_result : null;
		
		if (output)
		{
			output = Base64.decode(output);
		}
		else
		{
			output = "No results on python execution";
		}
		
		if (!jdoc.session_id)
		{
			$(output).appendTo(region);
		}
	},
	
	applyPython: function(p) {
		var me = this,
			region = me.region,
			execution_state,
			disp_data;
		
		if (me.execution_count > me._process_executed)
		{
			me.customLoad(true);
		}

		switch (p.msg_type)
		{
		case "status":
			if (p.content && p.content.execution_state)
			{
				execution_state = p.content.execution_state;
				
				switch (execution_state)
				{
				case "restarting":
					// something went wrong on execution
					me.customLoad(false);
					break;
				}
			}
			break;
		case "kernel_info_reply":
			break;
		case "comm_info_reply":
			break;
		case "display_data":
			disp_data = p.content.data ? p.content.data : null;
			$.each(disp_data, function(k, d) {
				if (k == "text/html")
				{
					var m = '<script type="text/javascript">',
						m1, m2, jscontent;
					
					if (d.indexOf(m) > -1 && true == false)
					{
						var head = $('head'),
							doc = document,
							jsmode,
							browser = window.bowser;
						
						jsmode = document.createElement('script'); // '<script id="clsscript" type="text/javascript"></script>');
						jsmode.id = 'clsscript';
						jsmode.type = 'text/javascript';
							
						head[0].appendChild(jsmode);
						
						m1 = d.indexOf(m);
						m2 = d.indexOf('</script>');
						
						jscontent = d.substring(m1 + m.length, m2);
						
						if (browser.msie)
						{
							jsmode.text = jscontent;
						}
						else
						{
							jsmode.innerHTML = jscontent;
						}
					}
					else
					{
						var dv = $("<div class='igc-code-block'></div>").appendTo(region);
						$(d).appendTo(dv);
					}
				}
				else if (k == "text/plain")
				{
					var dv = $("<div class='igc-code-block'></div>").appendTo(region);
					$('<pre>' + d + '</pre>').appendTo(dv);
				}
				else if (k == "image/png")
				{
					var dv = $("<div class='igc-code-block'></div>").appendTo(region);
					$("<img src='data:image/png;base64," + d + "'></img>").appendTo(dv);
				}
				else if (k == "application/vnd.plotly.v1+json")
				{
					var dv = $("<div class='igc-code-block'></div>").appendTo(region);
					$(p.content.data["text/html"]).appendTo(dv);
				}
				else
				{
					void 0;
				}
			});
			break;
		case "execute_reply":
			me._process_executed ++;
			if (me.execution_count <= me._process_executed)
			{
				me.customLoad(false);
			}
			break;
		case "error":
			disp_data = [
				p.content.ename,
				p.content.evalue
			];
			
			var dv = $("<div class='igc-code-block'></div>").appendTo(region);
			$.each(disp_data, function(k, d) {
				$("<span class='igc-code-error'>" + d + "</span>").appendTo(dv);
			});
			break;
		case "stream":
			if (p.content && p.content.name)
			{
				if (p.content.name == "stdout")
				{
					var d = p.content.text;
					var dv = $("<div class='igc-code-block'></div>").appendTo(region);
					$('<pre>' + d + '</pre>').appendTo(dv);
				}
				else
				{
					void 0;
				}
			}
			else
			{
				void 0;
			}
			break;
		default:
			void 0;
			break;
		}
	},
	
	customLoad: function(visible) {
		var me = this,
			btn,
			dom,
			lm,
			ldl

		if (visible)
		{
			lm = {
				msg: IRm$.r1("B_PROC") + " <button id='m-mec-loader'>" + IRm$.r1("B_PROC_CANCEL") + "</button>"
			};
			
			ld = me.setLoading(lm);
			
			dom = $(me.rendermask);
			// dom.width(me.getWidth()).height(me.getHeight());
			
			btn = $("#m-mec-loader", dom).bind("click", function() {
				me.cancelPython();
			});
		}
		else
		{
			me.setLoading(false, undefined, true);
		}
	},
	
	cancelPython: function() {
		var me = this,
			olapset = me.olapset,
			reportoption = me.reportoption,
			sheetobj = me.sheetobj,
			req = new IG$._rpc$(),
			session_id = me.session_id;
			
		void 0;
		
		me.execution_count = 0;
		
		if (olapset && olapset.jobid && session_id && reportoption)
		{
			req.init(me, 
				{
					ack: "olapservice",
					payload: {
						uid: reportoption.uid,
						jobid: olapset.jobid,
						active: "" + sheetobj.sheetindex,
						session_id: session_id,
						option: "cancel_python"
					},
					mbody: {}
				}, me, function(jdoc) {
						var me = this,
						tstatus = jdoc ? jdoc.status : null;
						
					if (tstatus == "S")
					{
						me.setLoading(false);
					}
				}, null);
			req.showerror = false;
			req.send();
		}
	},
	
	
	_ctrlwindow: function(cmd) {
		var me = this,
			dlg;

		switch (cmd)
		{
		case "cmd_py_edit":
			dlg = new IG$.d$PscrEdit({
				instance: me.instance,
				sheetoption: me.sheetoption,
				callback: new IG$.callBackObj(me, function() {
				})
			});
			IG$.checkLogin(this, dlg);
			break;
		}
	},
	
	init_f: function() {
		var me = this,
			w = me.getWidth(),
			h = me.getHeight(),
			sheet = me.body.dom,
			canvas = null,
			i;
			
		me._init = true;
		
		if (me.mresults)
		{
			me.applyReportResult(null, null, null, null, true);
		}
	},
	
	initComponent: function() {
		var me = this;
		
		$s.apply(me, {
			items: [
				{
					xtype: "panel",
					name: "rmain",
					layout: "card",
					items: [
						{
							name: "rgraph",
							xtype: "panel",
							layout: "fit",
							items: [
								{
									name: "rg",
									// xtype: "container",
									autoScroll: true,
									html: "<div id='notebook-container' class='notebook'></div>"
								}
							]
						}
					]
				}
			]
		});
		
		me.on("resize", function(p, w, h) {
			me.CLS.resize.call(me, w, h);
		});
		me.on("afterrender", function() {
			me.CLS.afterrender.call(me, me);
		});
		
		IG$.v$pyViewer.superclass.initComponent.call(me);
	},
	
	CLS: {
		resize: function(w, h) {
			var me = this;
			
			if (w > 0 && h > 0)
			{
				me.setPanelSize(w, h);
				
				me.sized = true;
				
				if (me.aftsized == true)
				{
					me.aftsized = false;
				}
			}
		},
		afterrender: function(sender) {
			this.init_f();
		}
	},
		
	setPanelSize: function(w, h) {
		var p = this;
		if (p.rt > -1)
		{
			clearTimeout(p.rt);
		}
		
		p.rt = setTimeout(function() {
		}, 20);
	},
	
	getDrillXML: function() {
		var dinfo = '';
		return dinfo;
	},
	
	getExportData: function(option, startx, starty, filetype, docid, d_width, d_height, callback) {
		var me = this,
			r = {},
			i,
			ix = startx, iy = starty, offset,
			sliceview,
			rview, svg, expdata,
			iw, ih,
			p = me.plotdata,
			gdom = me.rgraphzone;
		
		if (p && p.length > me.pg)
		{
			rview = p[me.pg];
			ix = startx;
			iy = starty;
			iw = IG$.j$ext._w(gdom);
			ih = IG$.j$ext._h(gdom);
			r = {
				type: "chart",
				x: ix,
				y: iy,
				d_width: d_width,
				d_height: d_height,
				width: iw,
				height: ih,
				docid: docid
			};
			if (filetype !== "SVG" && me.crv && me.crv[0] && me.crv[0].toDataURL)
			{
				r.image_data = {
					type: "png",
					data: me.crv[0].toDataURL("image/png")
				};
			}
			else
			{
				r.image_data = {
					type: "svg",
					data: Base64.encode(me.drPlot(gdom, rview, false).join(""))
				};
			}
		}
		
		callback.execute(r);
	},
	
	applyOptions: function(rop, sop) {
		var me = this;
		
		if (rop && sop)
		{
			me.reportoption = rop;
			me.sheetoption = sop;
		}
	}
});