IG$.d$PivotAdvOpt = $s.extend($s.window, {
	modal: true,
	layout: "fit",
	closable: false,
	resizable:false,
	width: 500,
	autoScroll: false,
	height: 550,
	maxHeight: 550,
	bodyPadding: ig$.padding,
	
	_confirm: function() {
		var me = this,
			sheetoption = me.sheetoption,
			mpos = 0, mval,
			cb_mloc = me.down("[name=cb_mloc]"),
			measureposition = me.down("[name=measureposition]"),
			measuregroup = me.down("[name=measuregroup]");
			
		if (sheetoption)
		{
			mval = cb_mloc.getGroupValue();
			mpos = measureposition.getValue();
			
			if (mval == "row" && sheetoption.model.rows.length < mpos)
			{
				mpos = sheetoption.model.rows.length;
			}
			else if (mval == "column" && sheetoption.model.cols.length < mpos)
			{
				mpos = sheetoption.model.cols.length;
			}
			
			mpos = (mpos < 0) ? 0 : mpos;
			
			$.each(me._f, function(i, f) {
				var mf = me.down("[name=" + f + "]"),
					v;
					
				switch (f)
				{
				case "measurelocation":
					v = mval;
					break;
				case "measureposition":
					v = mpos;
					break;
				case "customfix":
				case "usepaging":
				case "measuretitle":
					v = mf.getValue();
					break;
				default:
					v = mf.getValue();
					break;
				}
				
				sheetoption.model[f] = v;
			});
		}
		
		me.callback && me.callback.execute();
		me.close();
	},
	
	init_f: function() {
		var me = this,
			sheetoption = me.sheetoption;
		
		me._f = ["measurelocation", "measureposition", "measuretitle", "isdistinct", "treeview", "columntree", "isbigdecimal", "showlnum",
			"customfix", "customfixcols",
			"usepaging", "rowperpage", "pagestyle", "measureformat", "measureformatname", "fetchmode", "measuregroup"];
		
		if (sheetoption)
		{
			sheetoption.model.measureposition = (sheetoption.model.measureposition < 0) ? 0 : sheetoption.model.measureposition;
			
			$.each(me._f, function(i, f) {
				var mf = me.down("[name=" + f + "]"),
					v = sheetoption.model[f];
					
				switch (f)
				{
				case "measurelocation":
					mf.setValue({cb_mloc: [v]});
					break;
				case "customfix":
				case "usepaging":
				case "measuretitle":
					mf.setValue(v);
					f == "customfix" && me.down("[name=customfixcols]").setVisible(v);
					break;
				case "customfixcols":
					mf.setValue(v || 0);
					break;
				case "rowperpage":
					mf.setValue(v || 20);
					break;
				case "pagestyle":
					mf.setValue(v || "normal");
					break;
				default:
					mf.setValue(v);
					break;
				}
			});
		}
	},
	
	initComponent : function() {
		this.title = IRm$.r1("L_ADV_OPTION");
		
		$s.apply(this, {
			items: [
				{
					xtype: "panel",
					layout: "anchor",
					autoScroll: true,
					border: 0,
					defaults: {
						anchor: "100%"
					},
					fieldDefaults: {
						labelWidth: 100
					},
					padding: ig$.padding,
					items: [
						{
							xtype: "fieldset",
							title: IRm$.r1("L_M_POSITION"),
							collapsible: false,
							defaults: {
								anchor: "100%"
							},
							items: [
								{
									name: "measurelocation",
									fieldLabel: IRm$.r1("L_MEASURE_ON"),
									xtype: "radiogroup",
									plain: true,
									items: [
										{boxLabel: IRm$.r1("L_P_ROW"), name: "cb_mloc", inputValue: "row"},
										{boxLabel: IRm$.r1("L_P_COL"), name: "cb_mloc", inputValue: "column", checked: true}
									],
									listeners: {
									}
								},
								{
									xtype: "numberfield",
									name: "measureposition",
									fieldLabel: IRm$.r1("L_M_POSITION"),
									minValue: 0,
									maxValue: 99,
									value: 0,
									anchor: "60%"
								},
								{
									xtype: "checkbox",
									name: "measuretitle",
									fieldLabel: IRm$.r1("L_M_TITLE"),
									boxLabel: IRm$.r1("B_ENABLED")
								},
								{
									xtype: "fieldcontainer",
									fieldLabel: IRm$.r1("L_FIX_COLUMN"),
									layout: {
										type: "hbox",
										align: "stretch"
									},
									items: [
										{
											xtype: "checkbox",
											name: "customfix",
											boxLabel: IRm$.r1("L_CUSTOM_FIX"),
											listeners: {
												change: function(tobj, newValue, oldValue, eOpts) {
													var me = this,
														customfixcols = me.down("[name=customfixcols]");
														
													customfixcols.setVisible(newValue);
												},
												scope: this
											}
										},
										{
											xtype: "numberfield",
											name: "customfixcols",
											minValue: 0,
											maxValue: 10,
											value: 0
										}
									]
								},
								{
									xtype: "checkbox",
									name: "measuregroup",
									fieldLabel: IRm$.r1("L_M_GROUP"),
									boxLabel: IRm$.r1("B_ENABLED")
								}
							]
						},
						{
							xtype: "fieldset",
							layout: "anchor",
							title: IRm$.r1("L_M_FORMAT"),
							items: [
								{
									xtype: "textfield",
									fieldLabel: IRm$.r1("L_M_FORMAT"),
									name: "measureformat"
								},
								{
									xtype: "textfield",
									fieldLabel: IRm$.r1("L_M_NAME"),
									name: "measureformatname"
								},
								{
									xtype:"displayfield",
									value: "* Merge multiple measure in single column"
								}
							]
						},
						{
							xtype: "fieldset",
							layout: "anchor",
							title: IRm$.r1("L_PAGING"),
							items: [
								{
									xtype: "checkbox",
									name: "usepaging",
									fieldLabel: IRm$.r1("L_USE_PAGING"),
									boxLabel: IRm$.r1("B_ENABLED")
								},
								{
									xtype: "numberfield",
									name: "rowperpage",
									fieldLabel: IRm$.r1("L_ROW_P_PAGE"),
									minValue: 10,
									maxValue: 1000,
									value: 20
								},
								{
									xtype: "combobox",
									name: "pagestyle",
									fieldLabel: IRm$.r1("L_PAGE_STYLE"),
									queryMode: 'local',
									displayField: 'name',
									valueField: 'value',
									editable: false,
									autoSelect: true,
									store: {
										xtype: "store",
										fields: ["name", "value"],
										data: [
											{name: "Normal", value: "normal"},
											{name: "10 pages", value: "p10"},
											{name: "5 pages", value: "p5"},
											{name: "2 buttons", value: "button2"}
										]
									}
								}
							]
						},
						{
							xtype: "fieldset",
							title: IRm$.r1("L_TREE_VIEW"),
							collapsible: false,
							items: [
								{
									  xtype: "form",
									  layout: "anchor",
									  border: 0,
									  hidden: false,
									  defaults: {
										  anchor: "100%"
									  },
									  items: [
										  {
											  xtype: "checkbox",
											  boxLabel: IRm$.r1("L_ENABLE_TREE_VIEW"),
											  name: "treeview",
											  bodyPadding: ig$.padding
										  },
										  {
											  xtype: "checkbox",
											  boxLabel: IRm$.r1("L_COL_TREE"),
											  name: "columntree",
											  bodyPadding: ig$.padding
										  }
									  ]
								  }
							]
						},
						{
							xtype: "fieldset",
							title: IRm$.r1("L_OTHER_OPTION"),
							collapsible: false,
							items: [
								{
									xtype: "checkbox",
									fieldLabel: IRm$.r1("L_DISTINCT"),
									name: "isdistinct",
									boxLabel: IRm$.r1("B_ENABLED")
								},
								{
									xtype: "combobox",
									fieldLabel: IRm$.r1("L_FETCH_MODE"),
									name: "fetchmode",
									valueField: "value",
									displayField: "name",
									store: {
										data: [
											{name: IRm$.r1("B_DEFAULT"), value: ""},
											{name: IRm$.r1("L_FETCH_APPPAGE"), value: "fetch_page"},
											{name: IRm$.r1("L_FETCH_DBPAGE"), value: "fetch_page_db"},
											{name: IRm$.r1("L_FETCH_ALL"), value: "fetch_all"},
										]
									}
								},
								{
									xtype: "checkbox",
									fieldLabel: IRm$.r1("L_NUM_PREC"),
									boxLabel: IRm$.r1("L_HIGH_PREC"),
									bodyPadding: ig$.padding,
									name: "isbigdecimal"
								},
								{
									xtype: "checkbox",
									fieldLabel: IRm$.r1("L_LINE_NUM"),
									name: "showlnum",
									boxLabel: IRm$.r1("B_ENABLED")
								}
							]
						}
					]
				}
			],
			buttons: [
				{
					text: IRm$.r1('B_CONFIRM'),
					bodyCls: "ig-btn-confirm",
					handler: function() {
						this._confirm();
					},
					scope: this
				}, 
				{
					text: IRm$.r1('B_CANCEL'),
					handler:function() {
						this.close();
					},
					scope: this
				}
			]
		});
		
		IG$.d$PivotAdvOpt.superclass.initComponent.apply(this, arguments);
	},
	listeners: {
		afterrender: function(tobj) {
			tobj.init_f();
		}
	}
});