IG$.__util = {};

IG$.__util.msgbox = function(msg) {
	IG$.alertmsg(ig$.appname, msg, null, null, 1, "error");
}

IG$.__util._rcs = function(rcs, msg) {
	return msg;
}

IG$.__util.v_date = function(dt, sep) {
	var r = dt,
		dval;
	if (dt)
	{
		dval = [dt.substring(0, 4), dt.substring(4, 6), dt.substring(6, 8)];
		r = dval.join(sep);
	}
	
	return r;
};

IG$.__util.v_field = function(v, msg, title) {
	var r = true;
	
	if (!v)
	{
		r = false;
		
		if (msg)
		{
			IG$.alertmsg(title || ig$.appname, msg, null, null, 1, "error");
		}
	}
	
	return r;
}

IG$.controls = {};

IG$.ctrlBase = function(property, ctrl, dsmode) {
	var me = this;
	me.instance = ctrl && ctrl.owner ? ctrl.owner.instance : null;
	me.ctrl = ctrl;
	me.p = [
		{name: "visible", type: "property", datatype: "boolean", value: true},
		{name: "flex", type: "property", datatype: "number", value: 4},
		// {name: "border", type: "property", datatype: "number", value: 1},
		// {name: "bordercolor", type: "property", datatype: "color", value: "#e5e5e5"},
		// {name: "backgroundcolor", type: "property", datatype: "color"},
		// {name: "padding", type: "property", datatype: "number", value: 2},
		{name: "basecls", type: "property", datatype: "string"}
	];
	me.property = property;
	me._papp = {};
	me.applicationItem = null;
	
	me.getter = {};
	me.setter = {};
	
	me.dsmode = dsmode;
	
	me.html = $("<div id='" + (ctrl != null ? ctrl.ctrlname : "") + "' class='ig-db-ctrls ig-db-" + me.type + "'><div class='ig-db-title'></div><div class='ig-db-el'></div><div class='ig-db-sel'/></div>");
	me.el$ = $(".ig-db-el", me.html);
	me.tl$ = $(".ig-db-title", me.html);
	
	me.superclass = IG$.ctrlBase;
	
	me.initComponent();
}

IG$.ctrlBase.prototype = {
	__pcinit: function() {
		var me = this,
			key, 
			value;
		me.__pcinit_ = 1;
		
		for (key in me.property)
		{
			me.set(key, me.property[key]);
		}
		
		me.__pcinit_ = 0;
	},

	_get_id: function() {
		IG$._fcid = (IG$._fcid || 0);
		return "form_" + (IG$._fcid++);
	},
		
	get: function(fname) {
		var me = this;
		
		if (me.getter[fname])
		{
			return me.getter[fname].apply(me);
		}
		return null;
	},
	
	set: function(fname, value) {
		var me = this;
		if (me.setter[fname])
		{
			me.setter[fname](value);
		}
	},
	
	val: function(value) {
		return this[typeof(value) != "undefined" ? "set" : "get"]("text", value);
	},
	
	doGet: function(fname) {
		var me = this;
		
		if (me.getter[fname])
		{
			return me.getter[fname].apply(me);
		}
		return null;
	},
	
	doSet: function(fname, value) {
		var me = this;
		if (me.setter[fname])
		{
			me.setter[fname](value);
		}
	},
	
	invalidate: function() {
	},
	
	updateBorder: function() {
		var me = this,
			bsize = (me.dsmode ? 1 : me.property["border"]),
			borderstyle = "" + bsize + "px solid " + me.property["bordercolor"];
		me.html.css({border: borderstyle});
	},
	
	enabled: function(e) {
	},

	updateProperty: function(kname, value) {
		var me = this;
		
		me.property[kname] = value;
		
		if (me._papp[kname] == value)
			return;
			
		me._papp[kname] = value;
		
		switch (kname)
		{
		case "visible":
			if (value == false && !me.dsmode)
			{
				me.html.hide();
			}
			else
			{
				me.html.show();
			}
			break;
		case "fieldlabel":
			me.tl$ && me.tl$.html(value || "");
			me.lbl$ && me.lbl$.html(value || "");
			if (me.mp$)
				me.mp$.helperTextContent = value;
			break;
		case "border":
			me.updateBorder();
			break;
		case "bordercolor":
			me.updateBorder();
			break;
		case "basecls":
			value && me.html && me.html.addClass(value);
			break;
		case "flex":
			me.raiseEvent("validate");
			break;
		}
	},

	clearInvalid: function() {
		var me = this,
			html = me.html,
			cmp$ = me.cmp$;
		
		html && html.removeClass("ig-db-invalid");
		cmp$ && cmp$.removeClass("is-invalid");
		if (me.mp$) {me.mp$.valid = true};
	},

	markInvalid: function(feedback) {
		var me = this,
			html = me.html,
			cmp$ = me.cmp$;

		html.addClass("ig-db-invalid");
		cmp$ && cmp$.addClass("is-invalid");
		if (me.mp$) {me.mp$.valid = false};
	},
	
	initComponent: function() {
		var me = this;
		
		$.each(me.p, function(i, k) {
			if (k.type == "property")
			{
				if (typeof(k.value) != "undefined" && typeof(me.property[k.name]) == "undefined")
				{
					me.property[k.name] = k.value;
				}
				
				me.getter[k.name] = function() {
					return this.property[k.name];
				}
				
				me.setter[k.name] = function(value) {
					var ovalue = me.property[k.name];
					me.property[k.name] = value;
					if (me.superclass.prototype.updateProperty.apply(me, [k.name, value]) == false)
						return;
					me.updateProperty && me.updateProperty(k.name, value);
				}
			}
		});
	},

	trigger: function(ev) {
		this.triggerEvent(ev);
	},
	
	raiseEvent: function(ev) {
		var me = this;
		me.html.trigger("e_" + ev);
	},
	
	triggerEvent: function(evname, opt) {
		var me = this,
			ctrl = me.ctrl,
			owner = ctrl ? ctrl.owner : null,
			actionlist = ctrl ? ctrl.actionlist : null;
		
		if (!opt)
		{
			opt = {
				ctrl: me.ctrl,
				ptr: me,
				event: evname
			};
		}

		if (evname == "change")
		{
			owner._valueChangeHandler(me.ctrl);
		}
		
		if (actionlist && actionlist[evname])
		{
			owner.executeAction(actionlist[evname], opt);
		}
	},
	
	applyApplication: function () {
	},
	
	initDrawing: function() {
		var me = this;
		me.__pcinit();
	},

	dispose: function() {
	},
	_sync_val: function(mp, imp, seq) {
		var me = this,
			key = "_sync_val_timer_" + (seq || 0);

		me[key] && clearTimeout(me[key]);

		me[key] = setTimeout(function() {
			if (mp.value !== imp.val())
			{
				mp.value = imp.val();
			}
			else
			{
				me._sync_val(mp, imp, seq);
			}
		}, 100);
	},

	createNotch: function(label, fid) {
		return "<span class='mdc-notched-outline'><span class='mdc-notched-outline__leading'></span><span class='mdc-notched-outline__notch'><span class='mdc-floating-label' id='" + fid + "'>" + (label || "") + "</span></span><span class='mdc-notched-outline__trailing'></span></span><span class='mdc-text-field__ripple'></span>";
	},

	createTextField: function(ui, label) {
		var me = this,
			fid = me._get_id(),
			m = $("<label class='mdc-text-field mdc-text-field--outlined igc-md-ctrl igc-form-control' type='text'>" + me.createNotch(label, fid) + "<span class='mdc-text-field__affix mdc-text-field__affix--prefix'></span><input class='mdc-text-field__input' type='text' aria-labelledby='" + fid + "'><span class='mdc-text-field__affix mdc-text-field__affix--suffix'></span></label>").appendTo(ui)[0];

		return m;
	}
}

IG$.ctrlNullControl = IG$.extend(IG$.ctrlBase, {
	initComponent: function() {
		var me = this,
			ctrl = me.ctrl,
			thelp = $("<div>" + "unknown control: " + ctrl.ctrlname + "</div>");
			
		me.el$.append(thelp);
		me.superclass.prototype.initComponent.call(me);
	},
	
	initDrawing: function () {
		var me = this;
		
		me.html.css({border: '1px solid #a5a5a5'});
		me.__pcinit();
	}
});