IG$._FC_list = $s.extend(IG$._baseFC, {
	objtype: "list",
	s_codemap: 1,
	s_metric: 1,
	create: function(container) {
		var me = this,
			fitem = me.fitem,
			fmodel = me.fmodel,
			showpopup = fmodel.showpopup,
			browser = window.bowser,
			ui, lbl$, btnsel,
			rangevalue = fmodel.rangevalue,
			rangelabel = fmodel.rangelabel ? fmodel.rangelabel.split("^") : [],
            op = fmodel.operator,
            sellength = 0;

            if (op == "EQ" || op == "LIKE" || op == "GT" || op == "LT" || op == "GTE" || op == "LTE")
            {
                sellength = 1;
            }
            else if (op == "BETWEEN")
            {
                sellength = 2;
            }

			fid = me._get_id();
					
        ui = $("<div class='idv-sel-list'></div>")
            .appendTo(container);
        var m1,
            ml,
            Lt, Dt, S;
            
        me.mp$dv = me.createTextField(ui, fitem.model.title);
        // <div id='ms_" + fid + "' class='mdc-text-field-helper-text mdc-text-field-helper-text--validation-msg' aria-hidden='true'></div></div>
		lbl$ = me.lbl$ = $(".mdc-floating-label", me.mp$dv);
        $("inpput", me.mp$dv).bind("keyup", function(e) {
            var v = (mpsearch.value || "").toUpperCase();

            $.each(fitem.sdp, function(i, s) {
                if (v)
                {
                    if (s.md_view.selected || s.label_u.indexOf(v) > -1)
                    {
                        s.md_view.style.display = '';
                    }
                    else
                    {
                        s.md_view.style.display = 'none';
                    }
                }
                else
                {
                    s.md_view.style.display = '';
                }
            });
        });
        me.mp$ = mdc.textField.MDCTextField.attachTo(me.mp$dv);
        var $btn = $("<div class='idv-sel-combo-button idv-float-button'></div>").appendTo(ui);

        var sctrl,
			sbtn;

        sctrl = $("input", me.mp$dv);
            sbtn = $btn;

        sctrl.__c = true;
        sctrl.bind("input", function(e) {
            e.stopPropagation();
            e.stopImmediatePropagation();
            e.preventDefault();
            return false;
        });
        sctrl.bind("keydown", function(e) {
            if (e.key == "Escape")
            {
                this.value = "";
                ui[0].value = this.value;
                fitem._svalues = [];
                ui.trigger("change");
            }
            else if (e.keyCode == 8)
            {
                e.stopPropagation();
                e.stopImmediatePropagation();
                e.preventDefault();

                if (fitem._svalues.length)
                {
                    fitem._svalues.splice(fitem._svalues.length - 1, 1);
                    var lbl = [];
                    $.each(fitem._svalues, function(i, k) {
                        lbl.push(k.text || l.value);
                    });

                    this.value = lbl.join(",");
                    ui[0].value = this.value;
                    ui.trigger("change");
                }
            }
            else
            {
                e.stopPropagation();
                e.stopImmediatePropagation();
                e.preventDefault();

                return false;
            }
        });
        sctrl.bind("click", function(e) {
            $(this).select();
            sbtn.trigger("click");
        });


        sctrl.autocomplete({
            minLength: 0,
            sortResults: false,
            sortable: false,
            source: function(request, response) {
                var reqval = request.term,
                    eval = reqval.split(/,\s*/),
                    sdp = fitem.sdp;
                if (sdp)
                {
                    reqval = eval.pop();
                    
                    fitem.kdp = null;
                    
                    if (reqval && sdp.length > 190)
                    {
                        api_search(response, reqval);
                    }
                    else
                    {
                        response($.ui.autocomplete.filter(sdp, reqval));
                    }
                }
            },
            focus: function(e, ui) {
                return false;
            },
            select: function(e, mobj) {
                var svalue = mobj.item;
                
                if (!svalue.value && sellength == 1)
                {
                    if (fmodel.showallvalue)
                    {
                        this.value = "";
                        ui[0].value = this.value;
                        ui.trigger("change");
                    }
                }
                else if (svalue.value)
                {
                    if (sellength == 1)
                    {
                        this.value = svalue.label;
                        ui[0].value = this.value;
                        fitem._svalues = [
                            {
                                code: svalue.value,
                                text: svalue.label
                            }
                        ];
                    }
                    else if ((sellength == 2 && fitem._svalues.length < 2) || (sellength == 0))
                    {
                        var smap = {};
                        $.each(fitem._svalues, function(i, k) {
                            smap[k.codes] = i + 1;
                        });

                        if (smap[svalue.value])
                        {
                            fitem._svalues.splice(smap[svalue.value] - 1, 1);
                        }
                        else
                        {
                            fitem._svalues.push(
                                {
                                    code: svalue.value,
                                    text: svalue.label
                                }
                            );
                        }

                        var lbl = [];

                        $.each(fitem._svalues, function(i, k) {
                            lbl.push(k.text || k.value);
                        });

                        this.value = lbl.join(",");
                        ui[0].value = this.value;
                    }
                    ui.trigger("change");
                }
                
                if (browser.msie && sellength != 0)
                {
                    sctrl.blur();
                }
                return false;
            },
            open: function(e, mobj) {
                sctrl.__c = false;
            },
            close: function(e, mobj) {
                sctrl.__c = false;
                setTimeout(function() {
                    sctrl.__c = true;
                    if (browser.msie)
                    {
                        sctrl.blur();
                    }
                }, 1200);
            }
        });
        
        sctrl.bind("keydown", function(e) {
            if (e.keyCode === $.ui.keyCode.TAB) 
            {
                sctrl.__c = true;
                
                var vmenu = $(this).autocomplete("widget").menu;
                if (vmenu.active)
                {
                    e.preventDefault();
                }
            }
            else if (e.keyCode === $.ui.keyCode.ENTER)
            {
                var i,
                    m = 0,
                    l = sctrl.val().toLowerCase(), 
                    v,
                    sdp = fitem.sdp,
                    kdp = fitem.kdp,
                    kdp_i,
                    sdp_i;
                
                if (sdp && sdp.length && l)
                {
                    v = l.length;
                    
                    for (i=0; i < sdp.length; i++)
                    {
                        sdp_i = sdp[i];
                        if (sdp_i.label.substring(0, v).toLowerCase() == l)
                        {
                            fitem._svalues = [
                                {
                                    code: sdp_i.value,
                                    text: sdp_i.label
                                }
                            ];
                            sctrl.val(sdp_i.label);
                            ui[0].value = sdp_i.label;
                            // me.mp$ && me.mp$.update();
                            ui.trigger("change");
                            m = 1;
                            break;
                        }
                    }
                    
                    if (!m && kdp)
                    {
                        for (i=0; i < kdp.length; i++)
                        {
                            kdp_i = kdp[i];
                            if (kdp_i.label.substring(0, v).toLowerCase() == l)
                            {
                                fitem._svalues = [
                                    {
                                        code: kdp_i.value,
                                        text: kdp_i.label
                                    }
                                ];
                                sctrl.val(kdp_i.label);
                                ui[0].value = kdp_i.label;
                                // me.mp$ && me.mp$.update();
                                ui.trigger("change");
                                m = 1;
                                break;
                            }
                        }
                    }
                }
                if (m)
                {
                    sctrl.autocomplete("close");
                    sctrl.__c = true;
                }
            }
        });
        
        sbtn.bind("click", function(e) {
            e.stopImmediatePropagation();
            e.stopPropagation();
            e.preventDefault();
            
            if (sctrl.__c)
            {
                sctrl.__c = false;
                sctrl.autocomplete("search", ""); // filter value need to initialized
                sctrl.focus();
            }
            else
            {
                sctrl.__c = true;
                sctrl.autocomplete("close");
            }
        });

        ui.bind("change", function() {
            var bchanged = true,
                pkey = "__pval0",
                tval = sctrl.val(),
                sctrl_sel,
                sctrl_sel_code = "",
                i, placeholder = sctrl.attr("placeholder"),
                sdp = fitem.sdp,
                sdp_i;
            
            if (sdp && sdp.length)
            {
                for (i=0; i < sdp.length; i++)
                {
                    sdp_i = sdp[i];
                    
                    if (placeholder && tval == placeholder)
                    {
                        continue;
                    }
                    else if (sdp_i.value == tval || sdp_i.label == tval)
                    {
                        sctrl_sel =
                            {
                                code: sdp_i.value,
                                text: sdp_i.text || sdp_i.label
                            };
                        sctrl_sel_code = sctrl_sel.code;
                        break;
                    }
                }
            }
            
            if (fitem[pkey] == sctrl_sel_code)
            {
                bchanged = false;
            }
            
            if (bchanged)
            {
                me.clearInvalid();
                fitem[pkey] = sctrl_sel_code;
                
                if (fmodel.type == "valueset")
                {
                    fitem.value = [];
                    me.form.updateFilterValue(fitem);
                    
                    if (fitem.value && fitem.value.length && fitem.value[0].code)
                    {
                        var nvalue = fitem.value[0].code;
                        setTimeout(function() {
                            me.form._upd_vs_value.call(me.form, nvalue);
                        }, 10);
                    }
                    return false;
                }
                
                if (fmodel.isnecessary)
                {
                    !sctrl_sel_code && me.markInvalid("required");
                }
                
                // me.mp$ && me.mp$.update();
                me.trigger("change_val");
            }
        });

		return ui;
	},
	loadData: function(data) {
		var me = this,
			fmodel = me.fmodel,
			fitem = me.fitem,
			ui = me.ui,
            sctrl,
            sdp,
            dval,
			_init_value = fmodel._init_value || fmodel.initial_values,
            op = fmodel.operator,
            sellength = 0;

        if (op == "EQ" || op == "LIKE" || op == "GT" || op == "LT" || op == "GTE" || op == "LTE")
        {
            sellength = 1;
        }
        else if (op == "BETWEEN")
        {
            sellength = 2;
        }
			
        sdp = [];
        
        dval = me.getDefaultValue(fitem, 0);
        
        fitem._svalues = [];
        
        $.each(data, function(i, dt) {
            var sctrl = me.mp$,
			    sctrl1 = me.$mp$2;
			
			sdp = [];
			if (fmodel.showallvalue)
			{
				if (fmodel.isnecessary)
				{
					aname = fmodel.aname || IRm$.r1("L_SELECT_VALUE");
				}
				else
				{
					aname = fmodel.aname || IRm$.r1("L_ALL_VALUE");
				}
				
				sctrl.placeholder = aname;
				if (sctrl1)
					sctrl1.placeholder = aname;

				if (!fmodel.isnecessary)
					sdp.push({label: aname, value: ""});
			}
			
			dval = me.getDefaultValue(fitem, 0);
			
			fitem._svalues = [];
			
			for(let i=0; i < data.length; i++)
			{
				sdp.push({label: (data[i].disp || data[i].code), value: data[i].code});
				if (dval && dval == data[i].code)
				{
					if (fmodel.rangevalue)
					{
						fitem._svalues.push(
							{
								code: data[i].code,
								text: data[i].disp || data[i].code
							}
						);
					}
					else
					{
						fitem._svalues = [
							{
								code: data[i].code,
								text: data[i].disp || data[i].code
							}
						];
					}
				}
			}
			
			if (!fmodel.showallvalue && (!fitem._svalues || (fitem._svalues && fitem._svalues.length == 0)) && sdp.length)
			{
				fitem._svalues = [
					{
						code: sdp[0].value,
						text: sdp[0].label
					}
				];
				
				if (fmodel.rangevalue)
				{
					fitem._svalues.push({
						code: sdp[sdp.length-1].value,
						text: sdp[sdp.length-1].label
					});
				}
			}
			
			if (fitem._svalues && fitem._svalues.length)
			{
				sctrl.value = fitem._svalues[0].text;
				if (fmodel.rangevalue)
				{
					sctrl1.value = fitem._svalues[1].text;
				}
			}
			
			fitem.sdp = sdp;
        });

        if (!fmodel.showallvalue && (!fitem._svalues || (fitem._svalues && fitem._svalues.length == 0)) && sdp.length)
        {
            fitem._svalues = [
                {
                    code: sdp[0].value,
                    text: sdp[0].label
                }
            ];
        }
                
        fitem.sdp = sdp;
	},
	setValue: function(values, cmap, svalues) {
		var me = this,
			fmodel = me.fmodel,
			ui = me.ui,
			sctrl1;
			
		sctrl1 = me.mp$;
        sctrl1.value = values[0] || "";
	},
	updateValue: function(value) {
		var me = this,
			fitem = me.fitem,
			sval;
			
        sval = fitem._svalues;

        if (sval && sval.length)
        {
            for (let i=0; i < sval.length; i++)
            {
                value.push({
                    code: sval[i].code,
                    text: sval[i].text
                });
            }
        }
	},
	clear: function() {
		var me = this,
			fmodel = me.fmodel,
			ui = me.ui;
	},
	$setProp: function(fitem, key, value) {
		var me = this,
			fmodel = me.fmodel,
			ui = me.ui;
			
		switch(key)
		{
		case "placeholder":
			$.each(sctrls, function(m, mui) {
				mui && mui.attr("placeholder", value);
			});
			break;
		case "value":
			me.setValue([value]);
			break;
		case "labelField":
			break;
		case "valueField":
			break;
		}
		IG$._baseFC.prototype.$setProp.call(me, fitem, key, value);
	}
});

IG$.$FCinst["list"] = new IG$._FC_list();