IG$.globalReportStyle = $s.extend($s.window, {
	
	modal: true,
	region:"center",
	
	layout: "fit",
	
	closable: false,
	resizable: true,
	
	width: 650,
	height: 500,
		
	callback: null,
	
	ignoreBase: false,
	
	_init: function() {
		var me = this,
			req = new IG$._rpc$(),
			addr = {},
			reportoption = me.reportoption,
			pivotcontent = (reportoption ? reportoption.getCurrentPivot() : {});
		
		if (reportoption)
		{
			addr = {
				uid: reportoption._mc.uid,
				option: 'styleinfo',
				active: "" + me.activeSheet,
				theme_id: ig$.theme_id
			}
		}
		
		req.init(me, 
			{
				ack: "olapservice",
				payload: addr,
				mbody: pivotcontent,
				meta_type: me.meta_type || "report"
			}, me, me.rs_getStylInfo, null);
		req.send();
	},
	
	rs_getStylInfo: function(jdoc) {
		var me = this,
			tnode,
			tchild,
			i,
			styleitem,
			snode,
			dp = [],
			dpbase = [],
			stylemap = {},
			p, pname,
			targetitem = me.targetitem,
			target_name = targetitem ? targetitem.name + "_" + (targetitem.sequence || "0") : null,
			stylelist,
			rec;
		
		me.cbaseselect = me.down("[name=basestyle]");
		stylelist = me.stylelist = me.down("[name=stylelist]");
		
		me.styles = {
			app: []
		};
		
		tnode = jdoc.app_styles.default_styles;
		
		if (tnode != null)
		{
			for (i=0; i < tnode.length; i++)
			{
				styleitem = new IG$.clStyleObject(tnode[i], "appstyle", false);
				me.styles[styleitem.name] = styleitem;
				dpbase.push({name: styleitem.name});
			}
			
			for (i=0; i < dpbase.length; i++)
			{
				styleitem = me.styles[dpbase[i].name];
				if (styleitem.basestylename && me.styles[styleitem.basestylename])
				{
					styleitem.applyBaseStyle(me.styles[styleitem.basestylename]);
				}
			}
		}
		
		var appendStyle = function(tnode) {
			if (tnode)
			{
				var i,
					styleitem;
					
				for (i=0; i < tnode.length; i++)
				{
					styleitem = new IG$.clStyleObject(tnode[i], "appstyle", true);
					me.styles[styleitem.name] = styleitem;
					dpbase.push({name: styleitem.name});
					
					if (styleitem.basestylename && me.styles[styleitem.basestylename])
					{
						styleitem.applyBaseStyle(me.styles[styleitem.basestylename]);
					}
				}
			}
		}
		
		appendStyle(jdoc.app_styles.custom_styles);
		
		if (jdoc.cube_styles)
			appendStyle(jdoc.cube_styles.default_styels);
		
		if (jdoc.cube_styles)
			appendStyle(jdoc.cube_styles.custom_styles);
		
		if (jdoc.style_map)
		{
			for (i=0; i < jdoc.style_map.length; i++)
			{
				p = jdoc.style_map[i];
				pname = p.name + "_" + (p.rptseq || "0");
				stylemap[pname] = p.basename;
			}
		}
		
		if (jdoc.report_style)
		{
			tchild = jdoc.report_style;
			
			for (i=0; i < tchild.length; i++)
			{
				styleitem = new IG$.clStyleObject(tchild[i], "reportstyle", true);
				me.styles[styleitem.name + "_" + styleitem.rptseq] = styleitem;
				
				dp.push({name: styleitem.name, groupname: "Unit_" + styleitem.rptseq, rptseq: styleitem.rptseq});
				
				if (stylemap[styleitem.name + "_" + styleitem.rptseq])
				{
					styleitem.basestylename = stylemap[styleitem.name + "_" + styleitem.rptseq];
				}
				
				if (styleitem.basestylename != null && me.styles[styleitem.basestylename])
				{
					styleitem.applyBaseStyle(me.styles[styleitem.basestylename]);
				}
			}
		}
		
		me.cbaseselect.store.loadData(dpbase);
		stylelist.store.loadData(dp);
		
		if (target_name)
		{
			for (i=0; i < stylelist.store.data.items.length; i++)
			{
				rec = stylelist.store.data.items[i];
				
				if (rec.get("name") + "_" + rec.get("rptseq") == target_name)
				{
					stylelist.getSelectionModel().select(rec);
					
					me.updateStyleData();	
					me.loadStyleData(target_name);
					break;
				}
			}
		}
	},
	
	loadStyleData: function(stylename) {
		var me = this,
			styles = me.styles,
			bstyle;
		
		if (styles && styles[stylename])
		{
			var st = styles[stylename],
				seheader = me.down("[name=seheader]"),
				sedata = me.down("[name=sedata]"),
				basestyle = me.down("[name=basestyle]");
			
			me.editingstyle = st;
			
			me.ignoreBase = true;
			basestyle.setValue(st.basestylename || "");
			me.ignoreBase = false;

			if (st.basestylename && styles[st.basestylename])
			{
				bstyle = styles[st.basestylename];
			}
			
			seheader.loadStyleData(st.header, bstyle ? bstyle.header : null);
			sedata.loadStyleData(st.data, bstyle ? bstyle.data : null);
		}
	},
	
	updateStyleData: function() {
		var me = this;
		
		if (me.editingstyle)
		{
			var seheader = me.down("[name=seheader]"),
				sedata = me.down("[name=sedata]"),
				basestyle = me.down("[name=basestyle]");
			
			me.editingstyle.basestylename = basestyle.getValue();
			seheader.updateStyleData();
			sedata.updateStyleData();
		}
	},
	
	confirmChanges: function(b_apply) {
		var me = this,
			sheetoption = me.sheetoption,
			key, styles = me.styles,
			st, stt;
		
		me.updateStyleData();
		
		if (sheetoption)
		{
			sheetoption.model.styles = [];
			for (key in styles)
			{
				if (styles[key].itemtype == "reportstyle")
				{
					st = styles[key];
					stt = st.getData();
					if (st.basestylename && styles[st.basestylename])
					{
						stt = st.getData(styles[st.basestylename]);
					}
					sheetoption.model.styles.push(stt);
				}
			}
		}
		
		me.callback && me.callback.execute();
		
		if (!b_apply)
			me.close();
	},
	
	updateBaseStyle: function() {
		var me = this,
			editingstyle = me.editingstyle,
			basestyle = me.down("[name=basestyle]"),
			bstyle = me.styles[basestyle.getValue()];
			
		if (bstyle && editingstyle)
		{
			var seheader = me.down("[name=seheader]"),
				sedata = me.down("[name=sedata]");
				
			editingstyle.forceBsStyl(bstyle);
			
			seheader.loadStyleData(editingstyle.header);
			sedata.loadStyleData(editingstyle.data);
		}
	},
	
	initComponent : function() {
		var me = this;
		
		me.title = IRm$.r1("T_REPORT_STYLE");
		
		$s.apply(this, {
			items: [
				{
					xtype: "panel",
					layout: {
						type: "hbox",
						align: "stretch"
					},
					
					items: [
						{
							title: IRm$.r1("L_STYLE_ITEMS"), // "Style Items",
							layout: "fit",
							flex: 1,
							items: [
								{
									xtype: "grid",
									name: "stylelist",
									features: [
										{
											ftype: "grouping",
											groupHeaderTpl: "Folder: {groupname} ({rows.length} items)"
										}
									],
									store: {
										sorters: ["name"],
										groupField: "groupname",
										fields: [
											"name", "groupname", "rptseq"
										],
										data: []
									},
									hideHeaders: true,
									columns: [
										{
											text: IRm$.r1("B_NAME"),
											dataIndex: "name",
											tdCls: "igc-td-link",
											flex: 1
										}
									],
									listeners: {
										itemclick: function(view, record, item, index, e) {
											var me = this,
												bproc = false,
												data = record.data;
												
											me.updateStyleData();	
											me.loadStyleData(data.name + "_" + data.rptseq);
										},
										scope: this
									}
								}
							]
						},
						{
							xtype: "panel",
							layout: {
								type: "vbox",
								align: "stretch"
							},
							flex: 2,
							items: [
								{
									xtype: "combobox",
									name: "basestyle",
									fieldLabel: IRm$.r1("L_BASE_STYLE"), // Base Style",
									queryMode: "local",
									displayField: "name",
									valueField: "name",
									editable: false,
									autoSelect: true,
									store: {
										fields: [
											{name: "name"}
										]
									},
									listeners: {
										change: function() {
											if (this.ignoreBase == false)
											{
												this.updateBaseStyle();
											}
										},
										scope: this
									}
								},
								{
									xtype: "tabpanel",
									layout: "fit",
									plain: true,
									flex: 1,
									items: [
										new IG$.styleEditor({
											instance: me.instance,
											title: IRm$.r1("L_DATA_STYLE"), // "Data Style",
											name: "sedata",
											htype: "dt",
											flex: 1
										}),
										new IG$.styleEditor({
											instance: me.instance,
											title: IRm$.r1("L_HEAD_STYLE"), // "Header Style",
											name: "seheader",
											htype: "hd",
											flex: 1
										})
									]
								}
							]
						}
					]
				}
			],
			buttons:[
				{
					text: IRm$.r1("B_APPLY"),
					hidden: this.targetitem ? false : true,
					handler: function() {
						this.confirmChanges(1);
					},
					scope: this
				},
				"->",
				{
					text: IRm$.r1("B_CONFIRM"),
					bodyCls: "ig-btn-confirm",
					handler: function() {
						this.confirmChanges();
					},
					scope: this
				}, 
				{
					text: IRm$.r1("B_CANCEL"),
					handler:function() {
						this.close();
					},
					scope: this
				}
			],
			listeners: {
				afterrender: function(ui) {
					this._init();
				}
			}
		});
		
		IG$.passwordMgr.superclass.initComponent.apply(this, arguments);
	}
});