/**
 * calendar control
 */
IG$._FC_calendar = $s.extend(IG$._baseFC, {
	objtype: "calendar",
	s_codemap: 1,
	s_metric: 1,
	events: [
		{name: "change_val"}
	],
	create: function(container) {
		var me = this,
			fmodel = me.fmodel,
			fitem = me.fitem,
			browser = window.bowser,
			sheetoption = me.sheetoption,
			dateseltype = fmodel.dateseltype,
			calendar_locale = IG$.calendar_locale,
			ui = $("<div class='mec-dateperiod-box form-outline'></div>")
				.appendTo(container),
			ys = fmodel.yearfrom || "cyear-5", 
			ye = fmodel.yearto || "cyear",
			dt,
			_init_value = fmodel._init_value || fmodel.initial_values,
			fid = me._get_id();
			
		ys = me.getYearField(ys);
		ye = me.getYearField(ye);
		
		if (dateseltype == "year")
		{
			me.mp$dv = me.createTextField(ui, null);
			lbl$ = me.lbl$ = $(".mdc-floating-label", me.mp$dv);
			me.mp$ = mdc.textField.MDCTextField.attachTo(me.mp$dv);
			me.mp$.placeholder = calendar_locale.c1disp;

			var sbtn = $("<div class='idv-sel-combo-button idv-float-button'></div>").appendTo(ui),
				k = 0;

			var sctrl = $("input", ui[0]);

			sctrl.__c = true;
			sctrl.bind("input", function(e) {
				e.stopPropagation();
				e.stopImmediatePropagation();
				e.preventDefault();
				return false;
			});

			me.mp$dv.addEventListener("change", function() {
				me.trigger("change_val");
			});

			sctrl.autocomplete({
				minLength: 0,
				sortResults: false,
				sortable: false,
				source: function(request, response) {
					var reqval = request.term,
						eval = reqval.split(/,\s*/),
						sdp = fitem.sdp;
					if (sdp)
					{
						reqval = eval.pop();
						
						fitem.kdp = null;
						
						if (reqval && sdp.length > 190)
						{
							api_search(response, reqval);
						}
						else
						{
							response($.ui.autocomplete.filter(sdp, reqval));
						}
					}
				},
				focus: function(e, ui) {
					return false;
				},
				select: function(e, mobj) {
					var svalue = mobj.item;
					
					if (!svalue.value)
					{
						if (fmodel.showallvalue)
						{
							this.value = "";
							ui[0].value = this.value;
							ui.trigger("change");
						}
					}
					else
					{
						this.value = svalue.label;
						ui[0].value = this.value;
						fitem._svalues = [
							{
								code: svalue.value,
								text: svalue.label
							}
						];
						ui.trigger("change");
					}
					
					if (browser.msie)
					{
						sctrl.blur();
					}
					return false;
				},
				open: function(e, mobj) {
					sctrl.__c = false;
				},
				close: function(e, mobj) {
					sctrl.__c = false;
					setTimeout(function() {
						sctrl.__c = true;
						if (browser.msie)
						{
							sctrl.blur();
						}
					}, 1200);
				}
			});
			
			sctrl.bind("keydown", function(e) {
				if (e.keyCode === $.ui.keyCode.TAB) 
				{
					sctrl.__c = true;
					
					var vmenu = $(this).autocomplete("widget").menu;
					if (vmenu.active)
					{
						e.preventDefault();
					}
				}
				else if (e.keyCode === $.ui.keyCode.ENTER)
				{
					var i,
						m = 0,
						l = sctrl.val().toLowerCase(), 
						v,
						sdp = fitem.sdp,
						kdp = fitem.kdp,
						kdp_i,
						sdp_i;
					
					if (sdp && sdp.length && l)
					{
						v = l.length;
						
						for (i=0; i < sdp.length; i++)
						{
							sdp_i = sdp[i];
							if (sdp_i.label.substring(0, v).toLowerCase() == l)
							{
								fitem._svalues = [
									{
										code: sdp_i.value,
										text: sdp_i.label
									}
								];
								sctrl.val(sdp_i.label);
								ui[0].value = sdp_i.label;
								ui.trigger("change");
								m = 1;
								break;
							}
						}
						
						if (!m && kdp)
						{
							for (i=0; i < kdp.length; i++)
							{
								kdp_i = kdp[i];
								if (kdp_i.label.substring(0, v).toLowerCase() == l)
								{
									fitem._svalues = [
										{
											code: kdp_i.value,
											text: kdp_i.label
										}
									];
									sctrl.val(kdp_i.label);
									ui[0].value = kdp_i.label;
									ui.trigger("change");
									m = 1;
									break;
								}
							}
						}
					}
					if (m)
					{
						sctrl.autocomplete("close");
						sctrl.__c = true;
					}
				}
			});
			
			sbtn.bind("click", function(e) {
				e.stopImmediatePropagation();
				e.stopPropagation();
				e.preventDefault();
				
				if (sctrl.__c)
				{
					sctrl.__c = false;
					sctrl.autocomplete("search", ""); // filter value need to initialized
					sctrl.focus();
				}
				else
				{
					sctrl.__c = true;
					sctrl.autocomplete("close");
				}
			});
			
			ui.bind("change", function() {
				var bchanged = true,
					pkey = "__pval" + k,
					tval = sctrl.val(),
					sctrl_sel,
					sctrl_sel_code = "",
					i, placeholder = sctrl.attr("placeholder"),
					sdp = fitem.sdp,
					sdp_i;
				
				if (sdp && sdp.length)
				{
					for (i=0; i < sdp.length; i++)
					{
						sdp_i = sdp[i];
						
						if (placeholder && tval == placeholder)
						{
							continue;
						}
						else if (sdp_i.value == tval || sdp_i.label == tval)
						{
							sctrl_sel =
								{
									code: sdp_i.value,
									text: sdp_i.text || sdp_i.label
								};
							sctrl_sel_code = sctrl_sel.code;
							break;
						}
					}
				}
				
				if (fitem[pkey] == sctrl_sel_code)
				{
					bchanged = false;
				}
				
				if (bchanged)
				{
					me.clearInvalid();
					fitem[pkey] = sctrl_sel_code;
					
					if (fmodel.type == "valueset")
					{
						fitem.value = [];
						me.form.updateFilterValue(fitem);
						
						if (fitem.value && fitem.value.length && fitem.value[0].code)
						{
							var nvalue = fitem.value[0].code;
							setTimeout(function() {
								me.form._upd_vs_value.call(me.form, nvalue);
							}, 10);
						}
						return false;
					}
					
					if (fmodel.isnecessary)
					{
						!sctrl_sel_code && me.markInvalid("required");
					}
					
					// me.mp$ && me.mp$.update();
					me.trigger("change_val");
				}
			});
			
			me._pop_dtval(fitem, dt, dateseltype, 1, _init_value);
		}
		else if (dateseltype == "month")
		{
			ptn = "yyyy-mm";
			
			fitem.dt = $("<input type='text'></input>")
				.css({
					position: "absolute",
					top: 0,
					bottom: 0,
					left: 0,
					width: 0,
					border: 0
				})
				.appendTo(ui);

			me.mp$dv = me.createTextField(ui, null);
			lbl$ = me.lbl$ = $(".mdc-floating-label", me.mp$dv);
			me.mp$ = mdc.textField.MDCTextField.attachTo(me.mp$dv);
			me.mp$.placeholder = calendar_locale.c2disp;
			fitem.dt.bind("change", function(e) {
				me.mp$.value = fitem.dt.val();
			});

			$(me.mp$dv).bind("click", function(e) {
				e.preventDefault();
				e.stopImmediatePropagation();
				fitem.dt.monthpicker("show");
				me._sync_val(me.mp$, fitem.dt, 0);
			});

			fitem.dt.monthpicker({
				constrainInput: false,
				monthNames: $.datepicker._defaults.monthNamesShort,
				buttonImageOnly: true,
				pattern: ptn,
				dateFormat: calendar_locale.c2format,
				startYear: ys,
				finalYear: ye
			});
			
			fitem.dt.bind("change", function() {
				me.trigger("change_val");
			});

			fitem.dt.bind("monthpicker-change-year", function(sender, year) {
				let v = fitem.dt.monthpicker("getDate");
				let nyear = parseInt(year);

				if (v && nyear > 0 && v.getYear() != nyear)
				{
					v.setYear(nyear);
					fitem.dt.monthpicker("setDate", v);
				}
			});
			
			_init_value && _init_value.length && me._pop_dtval(fitem, fitem.dt, dateseltype, 1, _init_value);

			$("<div class='mec-dateperiod-button idv-float-button'>&nbsp;</div>").appendTo(ui).bind("click", function() {
				fitem.dt.monthpicker("show");
				me._sync_val(me.mp$, fitem.dt, 0);
			});
		}
		else
		{
			me.mp$dv = me.createTextField(ui, null);
			lbl$ = me.lbl$ = $(".mdc-floating-label", me.mp$dv);
			me.mp$ = mdc.textField.MDCTextField.attachTo(me.mp$dv);
			me.mp$.placeholder = calendar_locale.c1disp;
			me.mp$dv.addEventListener("change", function(e) {
				if (fitem.dt.val() != me.mp$.value)
					fitem.dt.val(me.mp$.value);
			});

			fitem.dt = $("<input type='text'></input>")
				.css({
					position: "absolute",
					top: 0,
					bottom: 0,
					left: 0,
					width: 0,
					border: 0
				})
				.appendTo(ui);

			fitem.dt.startYear = ys;
			fitem.dt.finalYear = ye;
			
			IG$.dateUtil.createDatePicker(me, fitem.dt, function(dateText, inst) {
				me.trigger("change_val");
			});
			
			_init_value && _init_value.length && me._pop_dtval(fitem, fitem.dt, dateseltype, 1, _init_value);
			
			$("<div class='mec-dateperiod-button idv-float-button'>&nbsp;</div>").appendTo(ui).bind("click", function() {
				fitem.dt.datepicker("show");
				me._sync_val(me.mp$, fitem.dt, 0);
			});
		}
		
		return ui;
	},
	setValue: function(values, cmap, svalues) {
		var me = this,
			fitem = me.fitem,
			dateseltype = me.fmodel.dateseltype;
			
		if (dateseltype == "year")
		{
			me.mp$.value = values[0];
		}
		else if (dateseltype == "month")
		{
			fitem.dt.monthpicker("setDate", me.getDefaultDate(values[0]));
			if (me.mp$) me.mp$.value = fitem.dt.val();
		}
		else
		{
			fitem.dt.datepicker("setDate", me.getDefaultDate(values[0]));
			if (me.mp$) me.mp$.value = fitem.dt.val();
		}
	},
	updateValue: function(value) {
		var me = this,
			fitem = me.fitem,
			dateseltype = me.fmodel.dateseltype,
			v;
			
		if (dateseltype == "year")
		{
			v = me.mp$.value;
		}
		else if (dateseltype == "month")
		{
			v = fitem.dt.monthpicker("getDate");
		}
		else
		{
			v = fitem.dt.datepicker("getDate");
		}
		
		if (v)
		{
			if (dateseltype == "year")
			{
			}
			else
			{
				v = v.format("Ymd"); //  + "000000";
			}
			value.push({code: v, value: v, valuetype: "date", dateseltype: dateseltype});
		}
	},
	clear: function() {
		var me = this,
			fitem = me.fitem,
			dateseltype = me.fmodel.dateseltype;
		if (dateseltype == "year")
		{
			fitem.dt[0].value = "";
		}
		else if (dateseltype == "month")
		{
			if (me.mp$) me.mp$.value = "";
			fitem.dt.monthpicker("setDate", null);
		}
		else
		{
			if (me.mp$) me.mp$.value = "";
			fitem.dt.datepicker("setDate", null);
		}
	}
});

IG$.$FCinst["calendar"] = new IG$._FC_calendar();