/***********************************************************************
 * AppPageControl: MonthField 
 */
 IG$.ctrlMonthField = IG$.extend(IG$.ctrlBase, {
	type: "monthchooser",
	initComponent: function() {
		var me = this;

		me.p.push(
			{name: "text", type: "property", datatype: "string"},
			{name: "fieldlabel", type: "property", datatype: "string"}
		);
		
		me.superclass.prototype.initComponent.call(me);
	},
	
	initDrawing: function () {
		var me = this,
			fid = me._get_id(),
			cdate = new Date();
		
		me.superclass.prototype.initDrawing.call(me);

		me.el$.addClass("form-outline");
		me.tl$ && me.tl$.hide();
		
		me.mp$ = me.createTextField(me.el$, me.property.fieldLabel);
		lbl$ = me.lbl$ = $(".mdc-floating-label", me.mp$);
		cmp$ = me.cmp$ = $("input", me.mp$);

		me.mp$.addEventListener("click", function(e) {
			me.datefield.monthpicker("show");
			me._sync_val(me.mp$, me.datefield, 0);
		});

		me.mp$.addEventListener("change", function(e) {
			if (me.datefield.val() != me.mp$.value)
				me.datefield.val(me.mp$.value);
		});

		me.mp$ = mdc.textField.MDCTextField.attachTo(me.mp$);

		me.datefield = $("<input type='text'></input>")
			.css({
				position: "absolute",
				top: 0,
				bottom: 0,
				left: 0,
				width: 0,
				border: 0
			})
			.appendTo(me.el$)
			.monthpicker({
				buttonImage: "./images/calendar.gif",
				buttonImageOnly: true,
				pattern: "yyyy-mm",
				onSelect: function(dateText, inst) {
					me.mp$.value = me.datefield.val();
				}
			});
	},
	
	invalidate: function () {
	},
	
	getValue: function(param) {
		var dt = this.datefield.getValue();
		if (dt)
		{
			var strdt = dt.format('Ymd');
			param.push({code: strdt, value: strdt});
		}
	}
});

IG$.controls.monthchooser = new IG$.ctrlMonthField({}, null);